-- Stage 3 checks. Read-only. Run: sqlcmd -S localhost -E -d EEMSuite_Northlake -W -s "|" -i checks.sql
-- Workflow/task discrepancies are expected until Step 3 is configured; they are not a completed-stage pass.
-- Added 2026-10-01 (Ridgeline Wind): the ridgeline_* checks and ksuu_wind_knots, and Ridgeline in the vendor,
-- gateway and task checks. The dates in the Ridgeline checks follow the assumed sample days in
-- 04-acceptance-runs.yaml; change them to the days actually delivered.
SET NOCOUNT ON;
IF DB_NAME() <> N'EEMSuite_Northlake'
    THROW 51000, 'Run the Northlake checker only in EEMSuite_Northlake.', 1;

