-- Match fields exposed by the current Gateway Types editor; legacy GWParamPos and Delimiter are not entry requirements.
PRINT '== gateway_types: empty when every gateway type in 02-gateways.yaml gatewayTypes has exactly its parameters (column, label ignoring case, type and predefined values); missing is a parameter or type to add, not in the recipe one to remove ==';
;WITH Expected AS (
    SELECT t.Name, p.Level, p.[Column], p.Label, p.Type, p.ValuesText
    FROM OPENJSON(@GatewayTypesJson, '$.types') WITH (Name nvarchar(128), Params nvarchar(max) AS JSON) t
    CROSS APPLY OPENJSON(t.Params) WITH (Level nvarchar(5), [Column] int, Label nvarchar(64), Type nvarchar(10), ValuesText nvarchar(max)) p
), Actual AS (
    SELECT v.Description AS Name, CASE WHEN p.GWParamID < 0 THEN N'node' ELSE N'point' END AS Level, ABS(p.GWParamID) AS [Column],
           p.GWParamLabel AS Label,
           CASE p.GWParamType WHEN 3 THEN N'Integer' WHEN 5 THEN N'Decimal' WHEN 11 THEN N'Boolean' WHEN 30 THEN N'String' ELSE CONCAT(N'code ', p.GWParamType) END AS Type,
           (SELECT STRING_AGG(CONCAT(x.GWParamValue, N'=', x.GWParamDescription), N'; ') WITHIN GROUP (ORDER BY x.GWParamValue COLLATE Latin1_General_100_BIN2)
            FROM dbo.GWVendorParamVal x WHERE x.GWVendParamID = p.GWVendParamID) AS ValuesText
    FROM dbo.GWVendorParam p JOIN dbo.GWVendor v ON v.GwVendorID = p.GwVendorID
    WHERE v.Description IN (SELECT Name FROM OPENJSON(@GatewayTypesJson, '$.types') WITH (Name nvarchar(128)))
)
SELECT COALESCE(e.Name, a.Name) AS GatewayType, COALESCE(e.Level, a.Level) AS Level, COALESCE(e.[Column], a.[Column]) AS [Column],
       CASE WHEN a.Name IS NULL THEN N'missing' WHEN e.Name IS NULL THEN N'not in the recipe' ELSE N'differs' END AS Issue,
       e.Label AS ExpectedLabel, a.Label AS ActualLabel, e.Type AS ExpectedType, a.Type AS ActualType,
       e.ValuesText AS ExpectedValues, a.ValuesText AS ActualValues
FROM Expected e FULL JOIN Actual a ON a.Name = e.Name AND a.Level = e.Level AND a.[Column] = e.[Column]
WHERE a.Name IS NULL OR e.Name IS NULL OR e.Label <> a.Label OR e.Type <> a.Type
   OR ISNULL(e.ValuesText, N'') <> ISNULL(a.ValuesText, N'') COLLATE Latin1_General_100_BIN2
ORDER BY 1, 2, 3;

PRINT '== gateway_type_assignments: empty when each configured profile uses its own expected type, including the three handheld gateways on Handheld Meter Reading Gateway (missing until Step 5 creates them); transitional Aeris is checked only while present ==';
SELECT expected.Name AS Gateway, expected.Vendor AS ExpectedType,
       actual.GatewayID, actual.Matches, vendor.Description AS ActualType,
       CASE WHEN actual.Matches=0 THEN N'missing gateway'
            WHEN actual.Matches>1 THEN N'ambiguous gateway'
            ELSE N'incorrect gateway type' END AS Issue
FROM OPENJSON(@GatewayTypesJson, '$.profiles')
     WITH (Name nvarchar(255), Vendor nvarchar(128), Required bit) expected
OUTER APPLY (SELECT COUNT(*) AS Matches, MIN(o.hSiERtdb) AS GatewayID, MIN(o.GwVendorID) AS VendorID
             FROM dbo.ObjectRegistry o WHERE o.Descriptor=expected.Name) actual
LEFT JOIN dbo.GWVendor vendor ON vendor.GwVendorID=actual.VendorID
WHERE (expected.Required=1 OR actual.Matches>0)
  AND (actual.Matches<>1 OR vendor.Description IS NULL OR vendor.Description<>expected.Vendor)
ORDER BY expected.Name;

PRINT '== gateway_node_parameters: empty when required nodes and their parameter values match the recipe, including UTC on the five MDEF/MV9 source-service nodes ==';
SELECT e.Gateway,e.Name AS Node,p.Label AS Parameter,p.Value AS ExpectedValue,a.Value AS ActualValue,
       CASE WHEN matched.Matches=0 THEN N'missing node' WHEN matched.Matches>1 THEN N'ambiguous node' ELSE N'incorrect node parameter' END AS Issue
FROM OPENJSON(@GatewayTypesJson,'$.nodes') WITH (Gateway nvarchar(255),Name nvarchar(255),Params nvarchar(max) AS JSON) e
OUTER APPLY (SELECT COUNT(*) Matches,MIN(n.GwNodeID) NodeID FROM dbo.GwNodes n
             JOIN dbo.ObjectRegistry g ON g.hSiERtdb=n.PtGatewayID WHERE g.Descriptor=e.Gateway AND n.Description=e.Name) matched
LEFT JOIN dbo.GwNodes n ON n.GwNodeID=matched.NodeID
OUTER APPLY OPENJSON(e.Params) WITH ([Column] int,Label nvarchar(128),Value nvarchar(255)) p
CROSS APPLY (SELECT CASE p.[Column]
    WHEN 1 THEN n.GwNodeParam1 WHEN 2 THEN n.GwNodeParam2 WHEN 3 THEN n.GwNodeParam3
    WHEN 4 THEN n.GwNodeParam4 WHEN 5 THEN n.GwNodeParam5 WHEN 6 THEN n.GwNodeParam6
    WHEN 7 THEN n.GwNodeParam7 WHEN 8 THEN n.GwNodeParam8 WHEN 9 THEN n.GwNodeParam9
    WHEN 10 THEN n.GwNodeParam10 WHEN 11 THEN n.GwNodeParam11 WHEN 12 THEN n.GwNodeParam12
    WHEN 13 THEN n.GwNodeParam13 WHEN 14 THEN n.GwNodeParam14 WHEN 15 THEN n.GwNodeParam15 END Value) a
WHERE matched.Matches<>1 OR ISNULL(p.Value,N'')<>ISNULL(a.Value,N'')
ORDER BY e.Gateway,e.Name,p.[Column];

PRINT '== gateway_types_retired: empty after obsolete types are removed and shared Weather Gateway is renamed to Aeris Weather Gateway; do not delete types still in use ==';
SELECT v.Description AS GatewayType, (SELECT COUNT(*) FROM dbo.ObjectRegistry r WHERE r.GwVendorID = v.GwVendorID) AS GatewaysUsingIt
FROM dbo.GWVendor v
WHERE v.Description IN (SELECT Name FROM OPENJSON(@GatewayTypesJson, '$.retired') WITH (Name nvarchar(128)))
ORDER BY v.Description;

PRINT '== gateway_types_unlisted: empty when every gateway type in the database is one 02-gateways.yaml lists (gatewayTypes or otherGatewayTypes) ==';
SELECT v.Description AS GatewayType
FROM dbo.GWVendor v
WHERE v.Description NOT IN (SELECT Name FROM OPENJSON(@GatewayTypesJson, '$.listed') WITH (Name nvarchar(128)))
ORDER BY v.Description;
GO

PRINT '== gateway_points_bound: 12 acquisition gateways with 26 nodes and 258 direct points (02-gateways.yaml), plus the three handheld gateways on Handheld Meter Reading Gateway with no nodes or points: their 204 HMR registers use Step 5, not GwNodeID assignments. HMR Events Publish has no gateway. Ridgeline SCADA File Imports has 2 nodes and 66 points, Northlake VED MDEF Interval Import 4 nodes and 9 points, Northlake NOAA Weather 6 nodes and 30 points ==';
SELECT o.Descriptor AS Gateway, v.Description AS Vendor, COUNT(DISTINCT n.GwNodeID) AS Nodes, COUNT(p.PtID) AS Points
FROM dbo.ObjectRegistry o
LEFT JOIN dbo.GWVendor v ON v.GwVendorID = o.GwVendorID
LEFT JOIN dbo.GwNodes n ON n.PtGatewayID = o.hSiERtdb
LEFT JOIN dbo.PointDef_TBL p ON p.GwNodeID = n.GwNodeID
WHERE o.Descriptor LIKE 'Northlake%' OR o.Descriptor LIKE 'Cedar Row%' OR o.Descriptor LIKE 'Ridgeline%'
GROUP BY o.Descriptor, v.Description
ORDER BY o.Descriptor;
GO

PRINT '== ridgeline_nodes_bound: the four observed Ridgeline nodes and their 73 points: FIG-RIDGELINE-TURBINES 60, FIG-RIDGELINE-MET-MAST 6, MV90-MDEF-VED-RIDGELINE 3 and NOAA-KSUU 4, every point still on Pacific, TimeZoneID 33, as Stage 2 left it (the SCADA clock is handled by the task Timestamp Type utc and OffsetTimeMinutes 480, not by a time zone, because FIG has no standard-time stamp type, finding 49; 23 would be the London-summer-time GMT row, finding 48) ==';
SELECT o.Descriptor AS Gateway, n.Description AS Node, COUNT(p.PtID) AS Points,
       MIN(p.TimezoneID) AS MinTimeZoneID, MAX(p.TimezoneID) AS MaxTimeZoneID
FROM dbo.GwNodes n
JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
LEFT JOIN dbo.PointDef_TBL p ON p.GwNodeID = n.GwNodeID
WHERE n.Description IN ('FIG-RIDGELINE-TURBINES', 'FIG-RIDGELINE-MET-MAST', 'MV90-MDEF-VED-RIDGELINE', 'NOAA-KSUU')
GROUP BY o.Descriptor, n.Description
ORDER BY o.Descriptor, n.Description;
GO

