-- END WORKFLOW EXPECTATIONS

DECLARE @Workflows table (Name nvarchar(255), WorkflowId int, Matches int, Document nvarchar(max), Expected nvarchar(max));
INSERT @Workflows
SELECT e.Name, a.WorkflowId, a.Matches, v.Document, e.Expected
FROM OPENJSON(@WorkflowJson, '$.workflows') WITH (Name nvarchar(255), DocumentId nvarchar(255), Expected nvarchar(max) '$' AS JSON) e
OUTER APPLY (SELECT COUNT(*) Matches, MIN(w.WorkflowId) WorkflowId
             FROM dbo.Workflow w
             WHERE (e.DocumentId IS NOT NULL AND w.DocumentId=e.DocumentId)
                OR (e.DocumentId IS NULL AND w.Name=e.Name)) a
LEFT JOIN dbo.Workflow w ON w.WorkflowId=a.WorkflowId
LEFT JOIN dbo.WorkflowVersion v ON v.WorkflowVersionId=w.CurrentVersionId AND v.WorkflowId=w.WorkflowId;

DECLARE @WorkflowIssues table (Category nvarchar(40), Item nvarchar(255), Field nvarchar(255),
                              Expected nvarchar(2000), Actual nvarchar(2000), Issue nvarchar(255));
INSERT @WorkflowIssues
SELECT N'Workflow', Name, N'Definition', N'1 current workflow', CONVERT(nvarchar(20), Matches),
       CASE WHEN Matches=0 THEN N'missing workflow' WHEN Matches>1 THEN N'ambiguous workflow' ELSE N'missing current version' END
FROM @Workflows WHERE Matches<>1 OR Document IS NULL;

INSERT @WorkflowIssues
SELECT N'Workflow', w.Name, N'Execution profile', JSON_VALUE(w.Expected, '$.ProfileName'), JSON_VALUE(w.Document, '$.profileName'), N'incorrect profile'
FROM @Workflows w
WHERE w.Matches=1 AND ISNULL(JSON_VALUE(w.Document, '$.profileName'), N'')<>JSON_VALUE(w.Expected, '$.ProfileName');

INSERT @WorkflowIssues
SELECT N'Workflow', w.Name, e.value, N'1 component', CONVERT(nvarchar(20), a.Matches), N'missing or duplicate component'
FROM @Workflows w CROSS APPLY OPENJSON(w.Expected, '$.Components') e
OUTER APPLY (SELECT COUNT(*) Matches FROM OPENJSON(w.Document, '$.nodes') WITH (ComponentId nvarchar(255) '$.componentId') n
             WHERE n.ComponentId=e.value) a
WHERE w.Matches=1 AND a.Matches<>1;

INSERT @WorkflowIssues
SELECT N'Workflow', w.Name, n.ComponentId, N'component from YAML', NULL, N'unexpected component'
FROM @Workflows w CROSS APPLY OPENJSON(w.Document, '$.nodes') WITH (ComponentId nvarchar(255) '$.componentId') n
WHERE NOT EXISTS (SELECT 1 FROM OPENJSON(w.Expected, '$.Components') e WHERE e.value=n.ComponentId);

INSERT @WorkflowIssues
SELECT N'Workflow link', w.Name, CONCAT(e.FromComponent, N'.', e.FromField, N' -> ', e.ToComponent, N'.', e.ToField),
       N'connected', N'missing', N'publication or HMR handoff is not connected'
FROM @Workflows w
CROSS APPLY OPENJSON(w.Expected, '$.Links') WITH (FromComponent nvarchar(100), FromField nvarchar(100), ToComponent nvarchar(100), ToField nvarchar(100)) e
WHERE w.Matches=1 AND NOT EXISTS (
    SELECT 1
    FROM OPENJSON(w.Document, '$.nodes') WITH (Id nvarchar(255) '$.id', ComponentId nvarchar(100) '$.componentId') src
    CROSS JOIN OPENJSON(w.Document, '$.nodes') WITH (Id nvarchar(255) '$.id', ComponentId nvarchar(100) '$.componentId') dst
    CROSS JOIN OPENJSON(w.Document, '$.links') WITH (FromNodeId nvarchar(255) '$.fromNodeId', FromField nvarchar(100) '$.fromField',
                                                   ToNodeId nvarchar(255) '$.toNodeId', ToField nvarchar(100) '$.toField') link
    WHERE src.ComponentId=e.FromComponent AND dst.ComponentId=e.ToComponent
      AND link.FromNodeId=src.Id AND link.ToNodeId=dst.Id AND link.FromField=e.FromField AND link.ToField=e.ToField);

INSERT @WorkflowIssues
SELECT N'Workflow parameter', w.Name, e.Name, COALESCE(e.Kind, N'exposed workflow parameter'),
       p.Kind, N'missing, duplicate or incompatible parameter definition'
FROM @Workflows w
CROSS APPLY OPENJSON(w.Expected, '$.Parameters') WITH (Name nvarchar(255), Kind nvarchar(100), Required bit) e
OUTER APPLY (SELECT COUNT(*) Matches, MAX(p.Kind) Kind, MAX(CONVERT(int,p.Required)) Required
             FROM OPENJSON(w.Document, '$.parameters') WITH (Name nvarchar(255) '$.name', Kind nvarchar(100) '$.valueKind', Required bit '$.isRequired') p
             WHERE p.Name=e.Name) p
WHERE w.Matches=1 AND (p.Matches<>1 OR (e.Kind IS NOT NULL AND (ISNULL(p.Kind,N'')<>e.Kind OR ISNULL(p.Required,-1)<>CONVERT(int,e.Required))));

INSERT @WorkflowIssues
SELECT N'Workflow binding', w.Name, CONCAT(e.Component, N'.', e.Field), e.Value, a.Value, N'parameter is not wired to the component'
FROM @Workflows w
CROSS APPLY OPENJSON(w.Expected, '$.Bindings') WITH (Component nvarchar(255), Field nvarchar(255), Value nvarchar(2000)) e
OUTER APPLY (SELECT MAX(p.value) Value FROM OPENJSON(w.Document, '$.nodes')
             WITH (ComponentId nvarchar(255) '$.componentId', [Values] nvarchar(max) '$.values' AS JSON) n
             CROSS APPLY OPENJSON(n.[Values]) p WHERE n.ComponentId=e.Component AND p.[key]=e.Field) a
WHERE w.Matches=1 AND ISNULL(a.Value,N'')<>e.Value;

DECLARE @Tasks table (Name nvarchar(255), TaskID int, TaskMatches int, WorkflowId int, ExpectedWorkflowId int,
                      PinnedVersionId int, Document nvarchar(max), Expected nvarchar(max));
INSERT @Tasks
SELECT e.Name, t.TaskID, t.Matches, task.WorkflowId, w.WorkflowId,
       CASE WHEN task.WorkflowPinMode=1 THEN task.PinnedVersionId END, COALESCE(pinned.Document,w.Document), e.Expected
FROM OPENJSON(@WorkflowJson, '$.tasks') WITH (Name nvarchar(255), Workflow nvarchar(255), Expected nvarchar(max) '$' AS JSON) e
LEFT JOIN @Workflows w ON w.Name=e.Workflow
OUTER APPLY (SELECT COUNT(*) Matches, MIN(TaskID) TaskID FROM dbo.Task_Tbl WHERE Name=e.Name) t
LEFT JOIN dbo.Task_Tbl task ON task.TaskID=t.TaskID
LEFT JOIN dbo.WorkflowVersion pinned ON task.WorkflowPinMode=1 AND pinned.WorkflowVersionId=task.PinnedVersionId AND pinned.WorkflowId=task.WorkflowId;

INSERT @WorkflowIssues
SELECT N'Task', Name, N'Task record', N'1 reusable task', CONVERT(nvarchar(20),TaskMatches), N'missing or duplicate task'
FROM @Tasks WHERE TaskMatches<>1;
INSERT @WorkflowIssues
SELECT N'Task definition',t.Name,N'Task group / minimum interval / scheduling',
       CONCAT(JSON_VALUE(t.Expected,'$.TaskGroup'),N' / ',JSON_VALUE(t.Expected,'$.MinIntervalSeconds'),N' / multiple schedules allowed'),
       CONCAT(g.Description,N' / ',d.MinIntervalSeconds,N' / CanSchedule=',d.CanSchedule,N' / SingleScheduleOnly=',d.SingleScheduleOnly),
       N'incorrect task definition'
FROM @Tasks t JOIN dbo.Task_Tbl d ON d.TaskID=t.TaskID LEFT JOIN dbo.TaskType g ON g.TaskTypeID=d.TaskTypeID
WHERE ISNULL(g.Description,N'')<>JSON_VALUE(t.Expected,'$.TaskGroup')
   OR d.MinIntervalSeconds<>TRY_CONVERT(int,JSON_VALUE(t.Expected,'$.MinIntervalSeconds'))
   OR ISNULL(d.CanSchedule,0)<>1 OR ISNULL(d.SingleScheduleOnly,1)<>0;
INSERT @WorkflowIssues
SELECT N'Execution target',t.Name,N'Machine / Run as',
       CONCAT(JSON_VALUE(t.Expected,'$.Machine'),N' / inherit service account'),
       CONCAT(x.MachineName,N' / ',x.RunAsProfileId),
       N'expected one active machine target using the inherited service account'
FROM @Tasks t
OUTER APPLY (SELECT COUNT(*) Matches,MIN(m.MachineName) MachineName,
                    MIN(CONVERT(int,m.IsActive)) Active,MAX(NULLIF(x.RunAsProfileId,N'')) RunAsProfileId
             FROM dbo.TaskExecutionTarget x LEFT JOIN dbo.Machine m ON m.MachineId=x.MachineId WHERE x.TaskID=t.TaskID) x
WHERE t.TaskMatches=1 AND (x.Matches<>1 OR ISNULL(x.MachineName,N'')<>JSON_VALUE(t.Expected,'$.Machine')
                          OR ISNULL(x.Active,0)<>1 OR x.RunAsProfileId IS NOT NULL);
INSERT @WorkflowIssues
SELECT N'Task', t.Name, N'Workflow', JSON_VALUE(t.Expected,'$.Workflow'), w.Name, N'wrong workflow'
FROM @Tasks t LEFT JOIN dbo.Workflow w ON w.WorkflowId=t.WorkflowId
WHERE t.TaskMatches=1 AND (t.ExpectedWorkflowId IS NULL OR t.WorkflowId<>t.ExpectedWorkflowId OR t.WorkflowId IS NULL);
INSERT @WorkflowIssues
SELECT N'Task', t.Name, N'Pinned workflow version', CONVERT(nvarchar(20),w.CurrentVersionId),
       CONVERT(nvarchar(20),t.PinnedVersionId), N'pinned version differs from the checked current workflow'
FROM @Tasks t JOIN dbo.Workflow w ON w.WorkflowId=t.WorkflowId
WHERE t.PinnedVersionId IS NOT NULL AND t.PinnedVersionId<>w.CurrentVersionId;

-- Task defaults are checked as stored. Required=true does not make a blank default invalid.
INSERT @WorkflowIssues
SELECT N'Task default', t.Name, e.Name, e.Value,
       CASE WHEN d.Protected=1 THEN N'<protected>' ELSE d.Value END,
       CASE WHEN d.Matches<>1 THEN N'missing or duplicate default parameter'
            WHEN wp.Name IS NULL THEN N'not exposed by the selected workflow version'
            WHEN d.Visible<>1 THEN N'parameter must be visible to the schedule editor'
            WHEN d.Required<>CONVERT(int,e.Required) THEN N'required metadata differs from the workflow'
            ELSE N'incorrect reusable default' END
FROM @Tasks t
CROSS APPLY OPENJSON(t.Expected,'$.Parameters') WITH (Name nvarchar(255), Value nvarchar(2000), Kind nvarchar(40),Required bit) e
OUTER APPLY (SELECT COUNT(*) Matches,MAX(d.ParamValue) Value,MAX(CONVERT(int,d.Visible)) Visible,MAX(CONVERT(int,d.Required)) Required,
                    MAX(CASE WHEN DATALENGTH(d.ParamProtectedValue)>0 THEN 1 ELSE 0 END) Protected
             FROM dbo.TaskParamsDefault d WHERE d.TaskID=t.TaskID AND d.ParamName=e.Name) d
OUTER APPLY (SELECT Name FROM OPENJSON(t.Document,'$.parameters') WITH (Name nvarchar(255) '$.name') wp WHERE wp.Name=e.Name) wp
WHERE t.TaskMatches=1 AND
      (d.Matches<>1 OR wp.Name IS NULL OR ISNULL(d.Visible,0)<>1 OR ISNULL(d.Required,-1)<>CONVERT(int,e.Required) OR d.Protected=1 OR
       CASE WHEN ISNULL(e.Value,N'')=N'' AND ISNULL(d.Value,N'')=N'' THEN 1
            WHEN e.Kind=N'Boolean' AND LOWER(d.Value) IN (LOWER(e.Value),CASE WHEN e.Value=N'true' THEN N'1' ELSE N'0' END) THEN 1
            WHEN e.Kind=N'Integer' AND TRY_CONVERT(decimal(38,6),d.Value)=TRY_CONVERT(decimal(38,6),e.Value) THEN 1
            WHEN e.Kind=N'DateTime' AND TRY_CONVERT(datetimeoffset,d.Value)=TRY_CONVERT(datetimeoffset,e.Value) THEN 1
            WHEN e.Kind=N'String' AND d.Value=e.Value THEN 1
            WHEN e.Name LIKE N'%Directory' AND REPLACE(d.Value,N'\\',N'\')=REPLACE(e.Value,N'\\',N'\') THEN 1 ELSE 0 END=0);

DECLARE @Schedules table (Name nvarchar(255), TaskName nvarchar(255), TaskID int, SavedTaskID int,
                          TaskItemID int, ItemMatches int, TaskScheduleID int, GatewayId int, GatewayMatches int,
                          ScheduleKind int, IntervalSeconds int, CronExpression nvarchar(255), TimeZoneId int, Active int,
                          Document nvarchar(max), Expected nvarchar(max));
INSERT @Schedules
SELECT e.Name,e.Task,t.TaskID,ti.TaskID,i.TaskItemID,i.Matches,ti.TaskScheduleID,g.GatewayId,g.Matches,
       s.ScheduleKind,s.IntervalSeconds,s.CronExpression,s.TimeZoneId,ti.Active,t.Document,e.Expected
FROM OPENJSON(@WorkflowJson,'$.schedules') WITH (Name nvarchar(255),Task nvarchar(255),Gateway nvarchar(255),Expected nvarchar(max) '$' AS JSON) e
LEFT JOIN @Tasks t ON t.Name=e.Task
OUTER APPLY (SELECT COUNT(*) Matches,MIN(TaskItemID) TaskItemID FROM dbo.TaskItems WHERE Description=e.Name) i
LEFT JOIN dbo.TaskItems ti ON ti.TaskItemID=i.TaskItemID
LEFT JOIN dbo.TaskSchedules s ON s.TaskScheduleId=ti.TaskScheduleID
OUTER APPLY (SELECT COUNT(*) Matches,MIN(hSiERtdb) GatewayId FROM dbo.ObjectRegistry WHERE Descriptor=e.Gateway) g;

INSERT @WorkflowIssues
SELECT N'Schedule',Name,N'Schedule record',N'1 named schedule',CONVERT(nvarchar(20),ItemMatches),N'missing or duplicate schedule'
FROM @Schedules WHERE ItemMatches<>1;
INSERT @WorkflowIssues
SELECT N'Schedule',Name,N'Task',TaskName,CONVERT(nvarchar(20),SavedTaskID),N'schedule must use the reusable task'
FROM @Schedules WHERE ItemMatches=1 AND TaskID IS NOT NULL AND SavedTaskID<>TaskID;
INSERT @WorkflowIssues
SELECT N'Recipe prerequisite',Name,N'Gateway',JSON_VALUE(Expected,'$.Gateway'),CONVERT(nvarchar(20),GatewayMatches),N'gateway prerequisite missing or ambiguous'
FROM @Schedules WHERE GatewayMatches<>1;
INSERT @WorkflowIssues
SELECT N'Schedule',s.Name,N'Execution target',JSON_VALUE(t.Expected,'$.Machine'),CONVERT(nvarchar(20),i.MachineID),N'schedule is not bound to the reusable task execution target'
FROM @Schedules s JOIN @Tasks t ON t.TaskID=s.TaskID JOIN dbo.TaskItems i ON i.TaskItemID=s.TaskItemID
WHERE s.ItemMatches=1 AND NOT EXISTS
      (SELECT 1 FROM dbo.TaskExecutionTarget x JOIN dbo.Machine m ON m.MachineId=x.MachineId
       WHERE x.ID=i.MachineID AND x.TaskID=s.TaskID AND m.MachineName=JSON_VALUE(t.Expected,'$.Machine'));
INSERT @WorkflowIssues
SELECT N'Schedule',s.Name,v.Field,v.Expected,v.Actual,N'incorrect schedule setting'
FROM @Schedules s
CROSS APPLY (VALUES
    (N'ScheduleKind',JSON_VALUE(s.Expected,'$.ScheduleKind'),CONVERT(nvarchar(255),s.ScheduleKind)),
    (N'IntervalSeconds',JSON_VALUE(s.Expected,'$.IntervalSeconds'),CONVERT(nvarchar(255),s.IntervalSeconds)),
    (N'CronExpression',JSON_VALUE(s.Expected,'$.CronExpression'),s.CronExpression),
    (N'TimeZoneId',JSON_VALUE(s.Expected,'$.TimeZoneId'),CONVERT(nvarchar(255),s.TimeZoneId))
) v(Field,Expected,Actual)
WHERE s.ItemMatches=1 AND ISNULL(v.Expected,N'')<>ISNULL(v.Actual,N'')
  AND (v.Field<>N'IntervalSeconds' OR JSON_VALUE(s.Expected,'$.ScheduleKind')=N'1')
  AND (v.Field<>N'CronExpression' OR JSON_VALUE(s.Expected,'$.ScheduleKind')=N'2');
INSERT @WorkflowIssues
SELECT N'Schedule',Name,N'Active',N'0 (disabled)',CONVERT(nvarchar(20),Active),N'must stay disabled until Step 4'
FROM @Schedules WHERE @RequireDisabledSchedules=1 AND ItemMatches=1 AND ISNULL(Active,-1)<>0;

-- Explicit schedule rows override task defaults, including a deliberately blank row.
-- Only the workflow default applies after a blank effective input; the task default must not leak back in.
INSERT @WorkflowIssues
SELECT N'Schedule parameter',s.Name,e.Name,value.ExpectedValue,
       CASE WHEN p.Protected=1 OR (p.Matches=0 AND d.Protected=1) THEN N'<protected>' ELSE value.ActualValue END,
       CASE WHEN p.Matches>1 OR d.Matches>1 THEN N'duplicate parameter'
            WHEN e.[Override]=1 AND p.Matches=0 THEN N'missing explicit schedule override'
            WHEN wp.Name IS NULL THEN N'not exposed by the selected workflow version'
            ELSE N'missing or incorrect effective value' END
FROM @Schedules s
CROSS APPLY OPENJSON(s.Expected,'$.Parameters') WITH (Name nvarchar(255),Value nvarchar(2000),Kind nvarchar(40),Required bit,[Override] bit) e
OUTER APPLY (SELECT COUNT(*) Matches,MAX(p.ParamValue) Value,MAX(CASE WHEN DATALENGTH(p.ParamProtectedValue)>0 THEN 1 ELSE 0 END) Protected
             FROM dbo.TaskParams p LEFT JOIN dbo.TaskParamsDefault d ON d.TaskDefaultParamID=p.TaskDefaultParamID
             WHERE p.TaskItemID=s.TaskItemID AND COALESCE(p.ParamName,d.ParamName)=e.Name) p
OUTER APPLY (SELECT COUNT(*) Matches,MAX(d.ParamValue) Value,MAX(CASE WHEN DATALENGTH(d.ParamProtectedValue)>0 THEN 1 ELSE 0 END) Protected
             FROM dbo.TaskParamsDefault d WHERE d.TaskID=s.TaskID AND d.ParamName=e.Name) d
OUTER APPLY (SELECT Name,DefaultValue FROM OPENJSON(s.Document,'$.parameters')
             WITH (Name nvarchar(255) '$.name',DefaultValue nvarchar(2000) '$.defaultValue') wp WHERE wp.Name=e.Name) wp
CROSS APPLY (SELECT CASE WHEN e.Name=N'GatewayId' THEN CONVERT(nvarchar(20),s.GatewayId) ELSE e.Value END ExpectedValue,
                    COALESCE(NULLIF(CASE WHEN p.Matches>0 THEN p.Value ELSE d.Value END,N''),NULLIF(wp.DefaultValue,N''),N'') ActualValue) value
WHERE s.ItemMatches=1 AND s.TaskID=s.SavedTaskID AND (e.Name<>N'GatewayId' OR s.GatewayMatches=1) AND
      (p.Matches>1 OR d.Matches>1 OR (e.[Override]=1 AND p.Matches=0) OR wp.Name IS NULL
       OR p.Protected=1 OR (p.Matches=0 AND d.Protected=1) OR
       CASE WHEN e.Required=1 AND value.ActualValue=N'' THEN 0
            WHEN ISNULL(value.ExpectedValue,N'')=N'' AND value.ActualValue=N'' THEN 1
            WHEN e.Kind=N'Boolean' AND LOWER(value.ActualValue) IN (LOWER(value.ExpectedValue),CASE WHEN value.ExpectedValue=N'true' THEN N'1' ELSE N'0' END) THEN 1
            WHEN e.Kind=N'Integer' AND TRY_CONVERT(decimal(38,6),value.ActualValue)=TRY_CONVERT(decimal(38,6),value.ExpectedValue) THEN 1
            WHEN e.Kind=N'DateTime' AND TRY_CONVERT(datetimeoffset,value.ActualValue)=TRY_CONVERT(datetimeoffset,value.ExpectedValue) THEN 1
            WHEN e.Kind=N'String' AND value.ActualValue=value.ExpectedValue THEN 1
            WHEN e.Name LIKE N'%Directory' AND REPLACE(value.ActualValue,N'\\',N'\')=REPLACE(value.ExpectedValue,N'\\',N'\') THEN 1 ELSE 0 END=0);

INSERT @WorkflowIssues
SELECT N'Task default',t.Name,d.ParamName,N'parameter exposed by workflow',NULL,N'obsolete task default'
FROM @Tasks t JOIN dbo.TaskParamsDefault d ON d.TaskID=t.TaskID
WHERE d.Visible<>0 AND NOT EXISTS (SELECT 1 FROM OPENJSON(t.Document,'$.parameters') WITH (Name nvarchar(255) '$.name') p WHERE p.Name=d.ParamName);
INSERT @WorkflowIssues
SELECT N'Schedule parameter',s.Name,COALESCE(p.ParamName,d.ParamName),N'parameter exposed by workflow',NULL,N'obsolete schedule override'
FROM @Schedules s JOIN dbo.TaskParams p ON p.TaskItemID=s.TaskItemID LEFT JOIN dbo.TaskParamsDefault d ON d.TaskDefaultParamID=p.TaskDefaultParamID
WHERE s.SavedTaskID=s.TaskID AND NOT EXISTS (SELECT 1 FROM OPENJSON(s.Document,'$.parameters') WITH (Name nvarchar(255) '$.name') v WHERE v.Name=COALESCE(p.ParamName,d.ParamName));
INSERT @WorkflowIssues
SELECT N'Schedule',t.Name,N'Unexpected schedule',N'only named schedules from YAML',i.Description,N'unlisted schedule on reusable task'
FROM @Tasks t JOIN dbo.TaskItems i ON i.TaskID=t.TaskID
WHERE NOT EXISTS (SELECT 1 FROM @Schedules s WHERE s.TaskItemID=i.TaskItemID AND s.SavedTaskID=s.TaskID);
INSERT @WorkflowIssues
SELECT N'Task',t.Name,N'Previous task name',N'reusable task from YAML',NULL,N'per-profile task must be renamed or retired after schedules are moved'
FROM dbo.Task_Tbl t WHERE t.Name IN (SELECT value FROM OPENJSON(@WorkflowJson,'$.retiredTasks'));
INSERT @WorkflowIssues
SELECT N'Task',t.Name,N'Unlisted workflow task',N'one reusable Northlake task per workflow',NULL,N'unlisted duplicate workflow task'
FROM dbo.Task_Tbl t JOIN @Workflows w ON w.WorkflowId=t.WorkflowId
JOIN dbo.TaskType g ON g.TaskTypeID=t.TaskTypeID
WHERE (t.Name LIKE N'Northlake %' OR t.Name LIKE N'Ridgeline %')
  AND g.Description IN (SELECT JSON_VALUE(Expected,'$.TaskGroup') FROM @Tasks)
  AND NOT EXISTS (SELECT 1 FROM @Tasks e WHERE e.TaskID=t.TaskID)
  AND t.Name NOT IN (SELECT value FROM OPENJSON(@WorkflowJson,'$.retiredTasks'));

PRINT '== workflows_and_tasks: check reusable task defaults and per-schedule values independently; ingestion is checked separately ==';
SELECT (SELECT COUNT(*) FROM @Workflows) ExpectedWorkflows,
       (SELECT COUNT(*) FROM @Workflows WHERE Matches=1 AND Document IS NOT NULL) PresentWorkflows,
       (SELECT COUNT(*) FROM @Tasks) ExpectedTasks,
       (SELECT COUNT(*) FROM @Tasks WHERE TaskMatches=1) PresentTasks,
       (SELECT COUNT(*) FROM @Schedules) ExpectedSchedules,
       (SELECT COUNT(*) FROM @Schedules WHERE ItemMatches=1 AND TaskID=SavedTaskID) CorrectlyBoundSchedules,
       COUNT(*) ConfigurationIssues FROM @WorkflowIssues;
SELECT Category,Item,Field,Expected,Actual,Issue FROM @WorkflowIssues ORDER BY Category,Item,Field;
SELECT t.Name Task,t.TaskID,s.Name Schedule,s.TaskItemID,s.TaskScheduleID,s.GatewayId,
       s.ScheduleKind,s.IntervalSeconds,s.CronExpression,s.TimeZoneId,s.Active
FROM @Tasks t LEFT JOIN @Schedules s ON s.TaskID=t.TaskID ORDER BY t.Name,s.Name;
-- END WORKFLOW CHECKS
GO

PRINT '== acquisuite_complete_day: on the file''s own day (stamps from 2024-01-15 00:00, the interval starts) 96 rows for each of the two Student Center points, kWh point sums to 2020, kW point maxes at 120; on EEM''s day (stamps after 00:00 up to and including the next 00:00, read as interval ends) 95 rows and 2010 kWh, the 00:00 row being January 14''s last interval to EEM (PRODUCT FINDING 73: no AcquiSuite setting says the file stamps interval starts) ==';
SELECT p.PtID, p.Description, w.DayCut, COUNT(*) AS Readings, SUM(a.Value) AS SumValue, MAX(a.Value) AS MaxValue,
       MIN(a.UTCTimeStamp) AS FirstUTC, MAX(a.UTCTimeStamp) AS LastUTC
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
JOIN (VALUES ('file day, interval starts', 0), ('EEM day, interval ends', 1)) w (DayCut, EndStamps)
  ON (w.EndStamps = 0 AND a.LocalTimeStamp >= '2024-01-15' AND a.LocalTimeStamp < '2024-01-16')
  OR (w.EndStamps = 1 AND a.LocalTimeStamp > '2024-01-15' AND a.LocalTimeStamp <= '2024-01-16')
WHERE o.Descriptor = 'Northlake Student Center AcquiSuite' AND n.Description = 'ASQ-VED-STUDENT'
GROUP BY p.PtID, p.Description, w.DayCut
ORDER BY p.PtID, w.DayCut DESC;
GO

PRINT '== replay_no_duplicates: after the complete-day file and its replay, each of the two Student Center points holds exactly 96 archived rows in all (not only on the file''s day, so a replay that wrote a shifted copy would add rows and FAIL), the kWh point summing to 2020 and the kW point peaking at 120. Rewritten 2026-11-10: the earlier version tested the archive primary key, which cannot fail ==';
SELECT p.PtID, p.Description, 96 AS ExpectedRows, COUNT(a.PtID) AS ArchivedRows, SUM(a.Value) AS SumValue, MAX(a.Value) AS MaxValue,
       CASE WHEN COUNT(a.PtID) = 0 THEN 'NOT LOADED'
            WHEN COUNT(a.PtID) <> 96 THEN 'FAIL'
            WHEN p.Description LIKE 'Delivered kWh%' AND ABS(SUM(a.Value) - 2020) > 0.001 THEN 'FAIL'
            WHEN p.Description LIKE 'Demand kW%' AND ABS(MAX(a.Value) - 120) > 0.001 THEN 'FAIL'
            ELSE 'PASS' END AS Status
FROM dbo.PointDef_TBL p
JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
LEFT JOIN dbo.AnalogArchive_TBL a ON a.PtID = p.PtID
WHERE o.Descriptor = 'Northlake Student Center AcquiSuite' AND n.Description = 'ASQ-VED-STUDENT'
GROUP BY p.PtID, p.Description
ORDER BY p.PtID;
GO

PRINT '== gap_then_backfill: same two points read 88/1780 after the gap file (the first AcquiSuite run), then 96/2020 after the backfill file; the complete-day file and its replay that follow leave 96/2020 ==';
SELECT p.PtID, p.Description, COUNT(*) AS Readings, SUM(a.Value) AS SumValue, MAX(a.Value) AS MaxValue
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
WHERE o.Descriptor = 'Northlake Student Center AcquiSuite' AND n.Description = 'ASQ-VED-STUDENT'
  AND a.LocalTimeStamp >= '2024-01-15' AND a.LocalTimeStamp < '2024-01-16'
GROUP BY p.PtID, p.Description
ORDER BY p.PtID;
GO

PRINT '== ridgeline_scada_day: one SCADA day, 2024-07-15 on the Pacific Standard clock (assumed day; change the dates to the file delivered). Each row is stamped at the end of its ten minutes, as EEM reads interval data, so the day is the stamps after UTC 2024-07-15 08:00 up to and including 2024-07-16 08:00. FIG-RIDGELINE-TURBINES: 50 analog points = 7200 readings and 10 Turbine State points = 1440 digital readings; FIG-RIDGELINE-MET-MAST: 6 points = 864 readings; FirstUTC 2024-07-15 08:10 and LastUTC 2024-07-16 08:00. FirstStoredLocal and LastStoredLocal verify the UTC-plus-offset workaround (PRODUCT FINDING 49): the right Pacific civil time, 2024-07-15 01:10 and 2024-07-16 01:00 in daylight time (predicted from the converter, to record) ==';
SELECT n.Description AS Node, 'AnalogArchive_TBL' AS ArchiveTable, COUNT(DISTINCT p.PtID) AS Points, COUNT(*) AS Readings,
       MIN(a.UTCTimeStamp) AS FirstUTC, MAX(a.UTCTimeStamp) AS LastUTC,
       MIN(a.LocalTimeStamp) AS FirstStoredLocal, MAX(a.LocalTimeStamp) AS LastStoredLocal
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
WHERE o.Descriptor = 'Ridgeline SCADA File Imports'
  AND a.UTCTimeStamp > '2024-07-15 08:00' AND a.UTCTimeStamp <= '2024-07-16 08:00'
GROUP BY n.Description
UNION ALL
SELECT n.Description, 'DigitalArchive_TBL', COUNT(DISTINCT p.PtID), COUNT(*),
       MIN(d.UTCTimestamp), MAX(d.UTCTimestamp), MIN(d.LocalTimestamp), MAX(d.LocalTimestamp)
FROM dbo.DigitalArchive_TBL d
JOIN dbo.PointDef_TBL p ON p.PtID = d.PtID
JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
WHERE o.Descriptor = 'Ridgeline SCADA File Imports'
  AND d.UTCTimestamp > '2024-07-15 08:00' AND d.UTCTimestamp <= '2024-07-16 08:00'
GROUP BY n.Description
ORDER BY 1, 2;
GO

PRINT '== ridgeline_scada_day_short_points: empty once the SCADA day has loaded; any row is a Ridgeline SCADA point that did not receive exactly 144 readings in that UTC day (a mistyped Point Alias reads 0) ==';
SELECT p.PtID, n.Description AS Node, p.Description AS Point, COUNT(r.PtID) AS Readings
FROM dbo.PointDef_TBL p
JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID AND o.Descriptor = 'Ridgeline SCADA File Imports'
LEFT JOIN (SELECT PtID, UTCTimeStamp FROM dbo.AnalogArchive_TBL
           UNION ALL
           SELECT PtID, UTCTimestamp FROM dbo.DigitalArchive_TBL) r
       ON r.PtID = p.PtID AND r.UTCTimeStamp > '2024-07-15 08:00' AND r.UTCTimeStamp <= '2024-07-16 08:00'
GROUP BY p.PtID, n.Description, p.Description
HAVING COUNT(r.PtID) <> 144
ORDER BY p.PtID;
GO

PRINT '== ridgeline_wtg07_outage: WTG-07 (SYN-RWL-M-0110007) against WTG-06 (0110006) over the gearbox outage, 71 SCADA days, the stamps after UTC 2025-02-11 08:00 up to and including 2025-04-23 08:00 (assumed both end days are outage days; ScadaDays puts a stamp at SCADA midnight in the day it ends): every point 10224 readings over 71 days on both turbines, a fault being lost production and not a gap; WTG-07 Generated kWh 10m and Active Power kW 10m SumValue 0 and MaxValue 0, Possible kW 10m SumValue above 0, Turbine State MinValue 2 and MaxValue 2 ==';
SELECT mt.SM_Code AS Meter, p.Description AS Point, COUNT(*) AS Readings,
       COUNT(DISTINCT CONVERT(date, DATEADD(MINUTE, -481, a.UTCTimeStamp))) AS ScadaDays,
       SUM(a.Value) AS SumValue, MIN(a.Value) AS MinValue, MAX(a.Value) AS MaxValue
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
JOIN dbo.MetaWorld_TBL w ON w.MetaWorldID = p.MetaWorldID
JOIN dbo.Meter mt ON mt.MetaWorldID = w.ParentID
WHERE mt.SM_Code IN ('SYN-RWL-M-0110006', 'SYN-RWL-M-0110007')
  AND a.UTCTimeStamp > '2025-02-11 08:00' AND a.UTCTimeStamp <= '2025-04-23 08:00'
GROUP BY mt.SM_Code, p.Description
UNION ALL
SELECT mt.SM_Code, p.Description, COUNT(*),
       COUNT(DISTINCT CONVERT(date, DATEADD(MINUTE, -481, d.UTCTimestamp))),
       SUM(CONVERT(float, d.Value)), MIN(CONVERT(float, d.Value)), MAX(CONVERT(float, d.Value))
FROM dbo.DigitalArchive_TBL d
JOIN dbo.PointDef_TBL p ON p.PtID = d.PtID
JOIN dbo.MetaWorld_TBL w ON w.MetaWorldID = p.MetaWorldID
JOIN dbo.Meter mt ON mt.MetaWorldID = w.ParentID
WHERE mt.SM_Code IN ('SYN-RWL-M-0110006', 'SYN-RWL-M-0110007')
  AND d.UTCTimestamp > '2025-02-11 08:00' AND d.UTCTimestamp <= '2025-04-23 08:00'
GROUP BY mt.SM_Code, p.Description
ORDER BY 1, 2;
GO

PRINT '== ksuu_wind_knots: KSUU Wind Speed (unit kn, the observation wind_kt element, PRODUCT FINDING 45) beside the met mast Hub-Height Wind Speed 10m averaged over the same UTC hour; MastHourKnots is the mast m/s times 1.943844 and KsuuOverMast should be of order 1, so a gross unit error would show (an airport and a hub-height mast will not agree closely) ==';
SELECT k.UTCTimeStamp AS KsuuUTC, k.Value AS KsuuStoredKnots, u.UN_Units AS KsuuUnit,
       m.MastHourMs, m.MastHourMs * 1.943844 AS MastHourKnots,
       k.Value / NULLIF(m.MastHourMs * 1.943844, 0) AS KsuuOverMast
FROM dbo.AnalogArchive_TBL k
JOIN dbo.PointDef_TBL kp ON kp.PtID = k.PtID AND kp.Description = 'KSUU Wind Speed'
JOIN dbo.GwNodes kn ON kn.GwNodeID = kp.GwNodeID AND kn.Description = 'NOAA-KSUU'
JOIN dbo.Unit u ON u.UN_UnitID = kp.UN_UnitID
OUTER APPLY (SELECT AVG(a.Value) AS MastHourMs
             FROM dbo.AnalogArchive_TBL a
             JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID AND p.Description = 'Hub-Height Wind Speed 10m'
             JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID AND n.Description = 'FIG-RIDGELINE-MET-MAST'
             WHERE DATEADD(HOUR, DATEDIFF(HOUR, 0, a.UTCTimeStamp), 0) = DATEADD(HOUR, DATEDIFF(HOUR, 0, k.UTCTimeStamp), 0)) m
ORDER BY k.UTCTimeStamp;
GO

PRINT '== ridgeline_mdef_channels: the three VEDRIDGE01 channels over Pacific local days, first and last day included. The MDEF gateway stamps each reading at the end of its fifteen minutes (MdefFileParser: start minute 01 plus the interval, less one), so a day is the stamps after its midnight up to and including the next, 00:15 to 24:00. Valley Electric cycle 1 reads on the 5th, so its bills run from the 5th to the 4th. Bill 2024-07-01 to 2024-08-04 (35 days, 3360 readings per point): SumValue 2496612 (channel 1, Exported kWh 15m), 4428 (channel 2, Station Service kWh 15m) and 858948 (channel 3, Reactive kVArh 15m). Bill 2025-01-05 to 2025-02-04 (31 days, 2976 readings): 418836, 46920 and 131664. Calendar July 2024 (31 days, 2976 readings): channel 1 sums to 2208612 and channel 2 to 3876 (net 2204736), channel 3 has no stated figure; the 2024-08-01 to 2024-08-04 remainder of the first bill is 288000 export and 552 station service. A single delivered day reads 96 readings per point (92 on 2025-03-09, 100 on 2024-11-03 and 2025-11-02) ==';
SELECT p.PtID, p.Description AS Point, w.Period, COUNT(*) AS Readings,
       COUNT(DISTINCT CONVERT(date, DATEADD(MINUTE, -1, a.LocalTimeStamp))) AS Days, SUM(a.Value) AS SumValue
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
JOIN (VALUES ('Calendar July 2024', '20240701', '20240801'),
             ('Bill 2024-07-01 to 2024-08-04', '20240701', '20240805'),
             ('Bill 2025-01-05 to 2025-02-04', '20250105', '20250205')) w (Period, FromLocal, ToLocal)
  ON a.LocalTimeStamp > w.FromLocal AND a.LocalTimeStamp <= w.ToLocal
WHERE o.Descriptor = 'Northlake VED MDEF Interval Import' AND n.Description = 'MV90-MDEF-VED-RIDGELINE'
GROUP BY p.PtID, p.Description, w.Period
ORDER BY p.PtID, w.Period;
GO

PRINT '== ridgeline_aggregates: the four Ridgeline aggregates; Registered 1 (PRODUCT FINDING 14: 0 until the product writes the PointAggregates_TBL row, and Recalculate then fails with 51081), Members 10, 10, 10 and 2, all Required; for the SCADA day 2024-07-15 (the stamps after UTC 2024-07-15 08:00 up to and including 2024-07-16 08:00) the three farm aggregates hold 144 readings each, and Ridgeline Net Export kWh 15m holds 96 for the Pacific day 2024-07-15 (after UTC 07:00 up to and including 2024-07-16 07:00) ==';
SELECT p.PtID, p.Description AS AggregatePoint, p.TimezoneID,
       CASE WHEN pa.ID IS NULL THEN 0 ELSE 1 END AS Registered,
       (SELECT COUNT(*) FROM dbo.PointAggregatePoints m WHERE m.AggregatePtID = p.PtID) AS Members,
       (SELECT COUNT(*) FROM dbo.PointAggregatePoints m WHERE m.AggregatePtID = p.PtID AND m.Required = 1) AS RequiredMembers,
       pa.LastAggregated, COUNT(a.PtID) AS Readings, SUM(a.Value) AS SumValue, MAX(a.Value) AS MaxValue
FROM dbo.PointDef_TBL p
LEFT JOIN dbo.PointAggregates_TBL pa ON pa.AggregatePtID = p.PtID
LEFT JOIN dbo.AnalogArchive_TBL a ON a.PtID = p.PtID
       AND ((p.Interval = 10 AND a.UTCTimeStamp > '2024-07-15 08:00' AND a.UTCTimeStamp <= '2024-07-16 08:00')
         OR (p.Interval = 15 AND a.UTCTimeStamp > '2024-07-15 07:00' AND a.UTCTimeStamp <= '2024-07-16 07:00'))
WHERE p.Description IN ('Ridgeline Farm Generated kWh 10m', 'Ridgeline Farm Active Power kW 10m', 'Ridgeline Farm Possible Power kW 10m', 'Ridgeline Net Export kWh 15m')
GROUP BY p.PtID, p.Description, p.TimezoneID, pa.ID, pa.LastAggregated
ORDER BY p.Description;
GO

PRINT '== ridgeline_period_totals: only once the full files are loaded (assumed built to the hand-made transfer statement and the generator bills). Windows are Pacific days written as UTC (UTC-07:00 in July, UTC-08:00 in January), cut the way the rate engine and Bill Generation cut them: the stamps after the first midnight up to and including the last, every stamp being an interval end; FirstLocal and LastLocal show the stored local stamps they cover. Pacific July is the stamps after UTC 2024-07-01 07:00 up to and including 2024-08-01 07:00, FirstLocal 2024-07-01 00:10 and LastLocal 2024-08-01 00:00 on the 10-minute points (00:15 and 00:00 on the 15-minute), 4464 readings per turbine point: WTG-01 to WTG-10 Generated kWh 238412, 233905, 229768, 226341, 224087, 225530, 222196, 219874, 217402 and 213869; Farm Generated kWh 10m 2251384 (the ten summed); Farm Possible Power kW 10m summed and divided by 6 = 2327960 kWh. Ridgeline Net Export kWh 15m is the export less the station service of the same days: Pacific July 2976 readings, 2204736 (2208612 less 3876); the first generator bill 2024-07-01 to 2024-08-04 (after UTC 2024-07-01 07:00 up to and including 2024-08-05 07:00) 3360 readings, 2492184 (2496612 less 4428); the winter bill 2025-01-05 to 2025-02-04 (after UTC 2025-01-05 08:00 up to and including 2025-02-05 08:00) 2976 readings, 371916 (418836 less 46920) ==';
SELECT mt.SM_Code AS Item, COUNT(*) AS Readings, SUM(a.Value) AS SumValue,
       MIN(a.LocalTimeStamp) AS FirstLocal, MAX(a.LocalTimeStamp) AS LastLocal
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID AND p.Description = 'Generated kWh 10m'
JOIN dbo.MetaWorld_TBL w ON w.MetaWorldID = p.MetaWorldID
JOIN dbo.Meter mt ON mt.MetaWorldID = w.ParentID AND mt.SM_Code LIKE 'SYN-RWL-M-0110%'
WHERE a.UTCTimeStamp > '2024-07-01 07:00' AND a.UTCTimeStamp <= '2024-08-01 07:00'
GROUP BY mt.SM_Code
UNION ALL
SELECT p.Description + ' (aggregate, Pacific July)', COUNT(*), SUM(a.Value), MIN(a.LocalTimeStamp), MAX(a.LocalTimeStamp)
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID AND p.Description = 'Ridgeline Farm Generated kWh 10m'
WHERE a.UTCTimeStamp > '2024-07-01 07:00' AND a.UTCTimeStamp <= '2024-08-01 07:00'
GROUP BY p.Description
UNION ALL
SELECT p.Description + ' (aggregate, kW sum / 6 = kWh, Pacific July)', COUNT(*), SUM(a.Value) / 6.0, MIN(a.LocalTimeStamp), MAX(a.LocalTimeStamp)
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID AND p.Description = 'Ridgeline Farm Possible Power kW 10m'
WHERE a.UTCTimeStamp > '2024-07-01 07:00' AND a.UTCTimeStamp <= '2024-08-01 07:00'
GROUP BY p.Description
UNION ALL
SELECT p.Description + ' (aggregate, Pacific July)', COUNT(*), SUM(a.Value), MIN(a.LocalTimeStamp), MAX(a.LocalTimeStamp)
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID AND p.Description = 'Ridgeline Net Export kWh 15m'
WHERE a.UTCTimeStamp > '2024-07-01 07:00' AND a.UTCTimeStamp <= '2024-08-01 07:00'
GROUP BY p.Description
UNION ALL
SELECT p.Description + ' (aggregate, bill 2024-07-01 to 2024-08-04)', COUNT(*), SUM(a.Value), MIN(a.LocalTimeStamp), MAX(a.LocalTimeStamp)
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID AND p.Description = 'Ridgeline Net Export kWh 15m'
WHERE a.UTCTimeStamp > '2024-07-01 07:00' AND a.UTCTimeStamp <= '2024-08-05 07:00'
GROUP BY p.Description
UNION ALL
SELECT p.Description + ' (aggregate, bill 2025-01-05 to 2025-02-04)', COUNT(*), SUM(a.Value), MIN(a.LocalTimeStamp), MAX(a.LocalTimeStamp)
FROM dbo.AnalogArchive_TBL a
JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID AND p.Description = 'Ridgeline Net Export kWh 15m'
WHERE a.UTCTimeStamp > '2025-01-05 08:00' AND a.UTCTimeStamp <= '2025-02-05 08:00'
GROUP BY p.Description
ORDER BY 1;
GO

PRINT '== task_runs: one TaskRun row per Run now / scheduled fire (the installed build keeps these in TaskRun; WorkflowRun no longer exists), Succeeded = 1, ErrorCount = 0 ==';
SELECT t.Name AS Task, wr.StartedAt, wr.EndedAt, wr.Succeeded, wr.ErrorCount, wr.WarningCount, wr.NodeCount
FROM dbo.TaskRun wr
JOIN dbo.TaskItems ti ON ti.TaskItemID = wr.TaskItemID
JOIN dbo.Task_Tbl t ON t.TaskID = ti.TaskID
WHERE t.Name LIKE 'Northlake%' OR t.Name LIKE 'Cedar Row%' OR t.Name LIKE 'Ridgeline%'
ORDER BY wr.StartedAt;
GO

PRINT '== handheld_configuration: nine read types and 204 registers on 192 meters (213 checks); all must PASS before the Step 4 handheld pack. Temporary acceptance mappings must not remain. ==';
-- BEGIN HANDHELD EXPECTATIONS
-- implementation/stage-3-gateways-and-data/02-gateways.yaml: SHA256 016a93c700ad1ceec3ace8142aa61c593c1bcbc5aee334e8ea28a3d62d33c5ac
