DECLARE @HmrTypes TABLE
(
    Description nvarchar(50), ERTType nvarchar(2), NumDials smallint, NumDecimals smallint,
    ReadTypeCode nvarchar(2), ReadDirection nvarchar(1), DemandRead nvarchar(1), TruncationFactor int
);
INSERT @HmrTypes SELECT * FROM OPENJSON(@HandheldJson,'$.readTypes') WITH
(
    Description nvarchar(50), ERTType nvarchar(2), NumDials smallint, NumDecimals smallint,
    ReadTypeCode nvarchar(2), ReadDirection nvarchar(1), DemandRead nvarchar(1), TruncationFactor int
);
-- One row per register. RegisterKind: Accumulator (the register and its generated Delta), Analog (an Analog register
-- and a separate Analog usage point, for a unit an Accumulator cannot take) or Demand (no register: the value is stored
-- as read on the Analog point named by UsageDescription; ReadingDescription is NULL).
DECLARE @HmrExpected TABLE
(
    [Key] nvarchar(128) PRIMARY KEY, RegisterKind nvarchar(12), Company nvarchar(64), MeterNumber nvarchar(100), MeterDescription nvarchar(256),
    ReadingDescription nvarchar(64), UsageDescription nvarchar(64), UsageUnit nvarchar(100), Cycle nvarchar(2), Route nvarchar(6),
    Sequence int, Active bit, BillCode nvarchar(1), MeterText nvarchar(100), ReadType nvarchar(50),
    Constant float, Prompt nvarchar(4), Channel int, ERTID nvarchar(10), TamperCode nvarchar(2), HighWarning int, LowWarning int
);
INSERT @HmrExpected SELECT * FROM OPENJSON(@HandheldJson,'$.meters') WITH
(
    [Key] nvarchar(128), RegisterKind nvarchar(12), Company nvarchar(64), MeterNumber nvarchar(100), MeterDescription nvarchar(256),
    ReadingDescription nvarchar(64), UsageDescription nvarchar(64), UsageUnit nvarchar(100), Cycle nvarchar(2), Route nvarchar(6),
    Sequence int, Active bit, BillCode nvarchar(1), MeterText nvarchar(100), ReadType nvarchar(50),
    Constant float, Prompt nvarchar(4), Channel int, ERTID nvarchar(10), TamperCode nvarchar(2), HighWarning int, LowWarning int
);
DECLARE @HmrResults TABLE (Section nvarchar(40), Item nvarchar(128), Status nvarchar(8), Detail nvarchar(1000));
INSERT @HmrResults
SELECT N'Read types', expected.Description,
    CASE WHEN counts.ExistingRows=1 AND matches.MatchingRows=1 THEN N'PASS' ELSE N'FAIL' END,
    CONCAT(N'Rows=',counts.ExistingRows,N'; exact format matches=',matches.MatchingRows)
FROM @HmrTypes expected
OUTER APPLY
(
    SELECT COUNT(*) AS ExistingRows
    FROM dbo.HMR_ReadType actual WHERE actual.Description=expected.Description
) counts
OUTER APPLY
(
    SELECT COUNT(*) AS MatchingRows FROM dbo.HMR_ReadType actual
    WHERE actual.Description=expected.Description
      AND actual.NumDials=expected.NumDials AND actual.NumDecimals=expected.NumDecimals
      AND actual.ReadTypeCode=expected.ReadTypeCode AND actual.ReadDirection=expected.ReadDirection
      AND actual.DemandRead=expected.DemandRead AND ISNULL(actual.ERTType,N'')=ISNULL(expected.ERTType,N'')
      AND ISNULL(actual.TruncationFactor,-1)=ISNULL(expected.TruncationFactor,-1)
) matches;

DECLARE @HmrResolved TABLE
(
    [Key] nvarchar(128), MeterID int, ReadingPtID int, UsagePtID int, HMR_MeterID int, HMR_ReadingID int, IsDemand bit,
    MeterMatches int, ReadingMatches int, UsageMatches int, AssignmentMatches int, ChannelMatches int
);
INSERT @HmrResolved
SELECT e.[Key], meter.MeterID, point.PtID, usage.PtID, assignment.HMR_MeterID, channel.HMR_ReadingID,
    CASE WHEN e.RegisterKind=N'Demand' THEN 1 ELSE 0 END,
    meter.Matches, point.Matches, usage.Matches,
    CASE WHEN assignment.Total=1 THEN assignmentMatch.Matches ELSE 0 END,
    CASE WHEN channel.Total=1 THEN channelMatch.Matches ELSE 0 END
FROM @HmrExpected e
OUTER APPLY
(
    SELECT COUNT(*) AS Matches, MAX(m.MetaWorldID) AS MeterID
    FROM dbo.Meter m JOIN dbo.MetaWorld_TBL mw ON mw.MetaWorldID=m.MetaWorldID
    JOIN dbo.Company_TBL company ON company.CompanyID=mw.CompanyID
    WHERE m.SM_Code=e.MeterNumber AND mw.Description=e.MeterDescription AND company.CompanyName=e.Company
      AND ISNULL(mw.DeleteInd,0)=0
) meter
OUTER APPLY
(
    SELECT COUNT(*) AS Matches, MAX(p.PtID) AS PtID
    FROM dbo.PointDef_TBL p JOIN dbo.MetaWorld_TBL mw ON mw.MetaWorldID=p.MetaWorldID
    WHERE mw.ParentID=meter.MeterID AND p.Description=e.ReadingDescription
      AND ((e.RegisterKind=N'Accumulator' AND p.PtType=3) OR (e.RegisterKind=N'Analog' AND p.PtType NOT IN (3,4)))
      AND mw.PtID=p.PtID AND ISNULL(mw.DeleteInd,0)=0
) point
OUTER APPLY
(
    SELECT COUNT(*) AS Matches, MAX(candidate.PtID) AS PtID
    FROM
    (
        -- A register's usage point is the Delta Point_Save generated behind it.
        SELECT p.PtID
        FROM dbo.PtRelatedData_TBL relation JOIN dbo.PointDef_TBL p ON p.PtID=relation.RelatedPtID
        JOIN dbo.MetaWorld_TBL mw ON mw.MetaWorldID=p.MetaWorldID
        JOIN dbo.Unit unit ON unit.UN_UnitID=p.UN_UnitID
        WHERE e.RegisterKind=N'Accumulator' AND relation.PtID=point.PtID AND relation.ReasonType=N'D' AND p.PtType=4
          AND mw.ParentID=meter.MeterID AND ISNULL(mw.DeleteInd,0)=0
          AND CONCAT(unit.UN_Name,N' - (',unit.UN_Units,N')')=e.UsageUnit
        UNION ALL
        -- An Analog register's or a demand read's usage point is its own Analog point under the meter.
        SELECT p.PtID
        FROM dbo.PointDef_TBL p JOIN dbo.MetaWorld_TBL mw ON mw.MetaWorldID=p.MetaWorldID
        JOIN dbo.Unit unit ON unit.UN_UnitID=p.UN_UnitID
        WHERE e.RegisterKind IN (N'Analog',N'Demand') AND mw.ParentID=meter.MeterID AND p.Description=e.UsageDescription
          AND p.PtType NOT IN (3,4) AND mw.PtID=p.PtID AND ISNULL(mw.DeleteInd,0)=0
          AND CONCAT(unit.UN_Name,N' - (',unit.UN_Units,N')')=e.UsageUnit
    ) candidate
) usage
OUTER APPLY
(
    SELECT MAX(m.HMR_MeterID) AS HMR_MeterID, COUNT(*) AS Total
    FROM dbo.HMR_Meter m WHERE m.MetaWorldID=meter.MeterID
) assignment
OUTER APPLY
(
    SELECT COUNT(*) AS Matches FROM dbo.HMR_Meter m
    WHERE m.HMR_MeterID=assignment.HMR_MeterID AND m.CycleID=e.Cycle AND m.RouteNumber=e.Route
      AND m.ReadSequence=e.Sequence AND m.active=e.Active AND m.BillCode=e.BillCode AND m.ReadingText=e.MeterText
) assignmentMatch
OUTER APPLY
(
    -- A meter can have several registers; its prompt tells them apart (HMR_Setup_Save allows one per meter).
    SELECT MAX(r.HMR_ReadingID) AS HMR_ReadingID, COUNT(*) AS Total
    FROM dbo.HMR_Reading r WHERE r.HMR_MeterID=assignment.HMR_MeterID AND r.TextPrompt=e.Prompt
) channel
OUTER APPLY
(
    SELECT COUNT(*) AS Matches
    FROM dbo.HMR_Reading r LEFT JOIN dbo.HMR_ReadType type ON type.HMR_ReadTypeID=r.HMR_ReadTypeID
    WHERE r.HMR_ReadingID=channel.HMR_ReadingID AND r.Ptid_Usage=usage.PtID
      AND (r.Ptid_Reading=point.PtID OR (e.ReadingDescription IS NULL AND r.Ptid_Reading IS NULL))
      AND type.Description=e.ReadType AND ABS(r.MeterConstant-e.Constant)<0.0000001
      AND r.TextPrompt=e.Prompt AND r.Channel=e.Channel
      AND ISNULL(r.ERTID,N'')=ISNULL(e.ERTID,N'') AND ISNULL(r.TamperCode,N'')=ISNULL(e.TamperCode,N'')
      AND (r.High1=e.HighWarning OR (r.High1 IS NULL AND e.HighWarning IS NULL))
      AND (r.Low1=e.LowWarning OR (r.Low1 IS NULL AND e.LowWarning IS NULL))
) channelMatch;

INSERT @HmrResults
SELECT N'Meter/channel mappings', resolved.[Key],
    CASE WHEN MeterMatches=1 AND ReadingMatches=CASE WHEN IsDemand=1 THEN 0 ELSE 1 END AND UsageMatches=1
            AND AssignmentMatches=1 AND ChannelMatches=1
        THEN N'PASS' ELSE N'FAIL' END,
    CONCAT(N'Meter=',MeterMatches,CASE WHEN IsDemand=1 THEN N'; demand read' ELSE CONCAT(N'; register=',ReadingMatches) END,
        N'; usage point=',UsageMatches,N'; route fields=',AssignmentMatches,N'; channel fields=',ChannelMatches)
FROM @HmrResolved resolved;
INSERT @HmrResults
SELECT N'Unexpected assignments', CONCAT(N'HMR_Meter ',m.HMR_MeterID), N'FAIL',
    CONCAT(N'MeterID=',m.MetaWorldID,N'; cycle=',m.CycleID,N'; route=',m.RouteNumber)
FROM dbo.HMR_Meter m WHERE NOT EXISTS (SELECT 1 FROM @HmrResolved e WHERE e.MeterID=m.MetaWorldID);
INSERT @HmrResults
SELECT N'Unexpected registers', CONCAT(N'HMR_Reading ',r.HMR_ReadingID), N'FAIL',
    CONCAT(N'MeterID=',m.MetaWorldID,N'; prompt=',r.TextPrompt)
FROM dbo.HMR_Reading r JOIN dbo.HMR_Meter m ON m.HMR_MeterID=r.HMR_MeterID
WHERE EXISTS (SELECT 1 FROM @HmrResolved e WHERE e.MeterID=m.MetaWorldID)
  AND NOT EXISTS (SELECT 1 FROM @HmrResolved e WHERE e.HMR_ReadingID=r.HMR_ReadingID);

SELECT Section,Item,Status,Detail FROM @HmrResults ORDER BY Section,Item;
SELECT e.Company,e.MeterNumber,e.MeterDescription,e.Cycle,e.Route,e.Sequence,e.Prompt,
    r.MeterID,r.ReadingPtID,r.UsagePtID,r.HMR_MeterID,r.HMR_ReadingID
FROM @HmrExpected e JOIN @HmrResolved r ON r.[Key]=e.[Key] ORDER BY e.Cycle,e.Route,e.Sequence,e.Prompt;
SELECT COUNT(*) AS Checks, SUM(CASE WHEN Status=N'PASS' THEN 1 ELSE 0 END) AS Passed,
    SUM(CASE WHEN Status=N'FAIL' THEN 1 ELSE 0 END) AS Failed FROM @HmrResults;
GO

PRINT '== baselines: 3 rows (06-baselines.yaml). Science Center Electric kWh Baseline and Science Center Chilled Water Ton-Hours Baseline on Rolling Day Type Forecast, Student Center Demand kW Baseline on Average of Top 5 Days; Display 1, RelatedCount 1, SameMeter 1, and MeasuredHasGateway 1 for each ==';
SELECT p.Description AS BaselinePoint, calc.Name AS Algorithm,
       CASE WHEN w.BaselineInd = 2 THEN 0 ELSE 1 END AS Display,
       measured.Description AS MeasuredPoint, measuredMeter.SM_Code AS MeasuredMeter,
       (SELECT COUNT(*) FROM dbo.PtRelatedData_TBL r2 WHERE r2.RelatedPtID = p.PtID AND r2.ReasonType = 'B') AS RelatedCount,
       CASE WHEN wm.ParentID = w.ParentID THEN 1 ELSE 0 END AS SameMeter,
       CASE WHEN measured.PtGatewayID IS NOT NULL THEN 1 ELSE 0 END AS MeasuredHasGateway
FROM dbo.PointBaseLine b
JOIN dbo.PointDef_TBL p ON p.PtID = b.PtID
JOIN dbo.MetaWorld_TBL w ON w.MetaWorldID = p.MetaWorldID
LEFT JOIN dbo.curBaselineCalc calc ON calc.curBaselineCalcID = b.CurBaselineCalcID
LEFT JOIN dbo.PtRelatedData_TBL r ON r.RelatedPtID = p.PtID AND r.ReasonType = 'B'
LEFT JOIN dbo.PointDef_TBL measured ON measured.PtID = r.PtID
LEFT JOIN dbo.MetaWorld_TBL wm ON wm.MetaWorldID = measured.MetaWorldID
LEFT JOIN dbo.Meter measuredMeter ON measuredMeter.MetaWorldID = wm.ParentID
WHERE p.CompanyID > 0
ORDER BY p.Description;
GO

-- ============================================================================================================
-- Added 2026-11-10. Every section below returns Expected beside Actual and a Status: PASS, FAIL, or NOT LOADED
-- when the data the check reads is not in the database yet (that is not a failure). Read-only.
-- ============================================================================================================

PRINT '== node_scheduling_flags: the node flags 02-gateways.yaml sets. Enable Data Gaps 1 on NOAA-KSAC, NOAA-KSMF and NTP-BACNET-PLANT-HEADERS (live-polled feeds); Enable Late Intervals 1 and a Next Batch Method other than Disabled on ASQ-VED-STUDENT, MV90-MDEF-VED-SCIENCE and FIG-CEDAR-ROW-A-UNITS (feeds that arrive by file); ASQ-VED-LAKEVIEW disabled (AcquiSuite node IsEnabled 0) and the Lakeview Hall laundry point Disabled 1 on the FIG campus node (the EV point stays 0); every other node has both flags off ==';
SELECT x.Node, x.Item, x.Expected, x.Actual,
       CASE WHEN x.Actual IS NULL THEN 'NOT ENTERED' WHEN x.Actual = x.Expected THEN 'PASS' ELSE 'FAIL' END AS Status
FROM (
    SELECT e.Node, e.Item, e.Expected,
           CASE e.Item WHEN 'Enable Data Gaps' THEN CONVERT(int, n.EnableDataGaps)
                       WHEN 'Enable Late Intervals' THEN CONVERT(int, ISNULL(n.EnableLateIntervals, 0))
                       WHEN 'Next Batch Method is not Disabled' THEN CASE WHEN ISNULL(n.NextBatchMethodID, 0) > 0 THEN 1 ELSE 0 END
                       WHEN 'IsEnabled (node parameter 1)' THEN TRY_CONVERT(int, n.GwNodeParam1) END AS Actual
    FROM (VALUES ('NOAA-KSAC', 'Enable Data Gaps', 1), ('NOAA-KSMF', 'Enable Data Gaps', 1), ('NTP-BACNET-PLANT-HEADERS', 'Enable Data Gaps', 1),
                 ('ASQ-VED-STUDENT', 'Enable Late Intervals', 1), ('MV90-MDEF-VED-SCIENCE', 'Enable Late Intervals', 1), ('FIG-CEDAR-ROW-A-UNITS', 'Enable Late Intervals', 1),
                 ('ASQ-VED-STUDENT', 'Next Batch Method is not Disabled', 1), ('MV90-MDEF-VED-SCIENCE', 'Next Batch Method is not Disabled', 1), ('FIG-CEDAR-ROW-A-UNITS', 'Next Batch Method is not Disabled', 1),
                 ('ASQ-VED-LAKEVIEW', 'IsEnabled (node parameter 1)', 0), ('ASQ-VED-STUDENT', 'IsEnabled (node parameter 1)', 1)) e (Node, Item, Expected)
    LEFT JOIN dbo.GwNodes n ON n.Description = e.Node
    UNION ALL
    SELECT N'Lakeview Hall laundry point', 'Disabled (point parameter 1)', 1, TRY_CONVERT(int, p.GwPtParam1)
    FROM (SELECT 1 AS One) o LEFT JOIN dbo.PointDef_TBL p ON p.GwPtParam2 = 'FN_LAKEVIEW_LAUNDRY_E'
    UNION ALL
    SELECT N'Parking Structure EV point', 'Disabled (point parameter 1)', 0, TRY_CONVERT(int, p.GwPtParam1)
    FROM (SELECT 1 AS One) o LEFT JOIN dbo.PointDef_TBL p ON p.GwPtParam2 = 'FN_PARKING_EV_E'
    UNION ALL
    SELECT N'every other node', 'nodes with a flag on that the recipe does not name', 0,
           (SELECT COUNT(*) FROM dbo.GwNodes n
            WHERE (n.EnableDataGaps <> 0 OR ISNULL(n.EnableLateIntervals, 0) <> 0)
              AND n.Description NOT IN ('NOAA-KSAC', 'NOAA-KSMF', 'NTP-BACNET-PLANT-HEADERS', 'ASQ-VED-STUDENT', 'MV90-MDEF-VED-SCIENCE', 'FIG-CEDAR-ROW-A-UNITS'))
) x
ORDER BY x.Item, x.Node;
GO

PRINT '== central_plant_tou_period_totals: the Central Plant bill ved_central_plant_2024_09 (2024-08-05 to 2024-09-04, local stamps after 2024-08-05 00:00 up to and including 2024-09-05 00:00), cut the way the Stage 4 time-of-use grids cut it: each stamp is an interval end, counted in the hour it ends in; weekdays 12:00-18:00 are peak, weekdays 08:00-12:00 and 18:00-22:00 part-peak, everything else (nights, weekends, Labor Day 2024-09-02) off-peak. Expected 412800 peak, 368400 part-peak and 731200 off-peak kWh (1512400 in all), 528, 704 and 1744 intervals, 2976 readings on each of the two points and a 3240 kW maximum ==';
WITH s AS (
    SELECT p.Description AS Pt, a.Value,
           CONVERT(date, DATEADD(MINUTE, -1, a.LocalTimeStamp)) AS D, DATEPART(HOUR, DATEADD(MINUTE, -1, a.LocalTimeStamp)) AS H
    FROM dbo.AnalogArchive_TBL a
    JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
    JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
    JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
    WHERE o.Descriptor = 'Northlake VED MDEF Interval Import' AND n.Description = 'MV90-MDEF-VED-PLANT'
      AND a.LocalTimeStamp > '20240805' AND a.LocalTimeStamp <= '20240905'),
c AS (
    SELECT Pt, Value,
           CASE WHEN DATEDIFF(DAY, '19000101', D) % 7 < 5 AND D <> '20240902'
                THEN CASE WHEN H >= 12 AND H < 18 THEN 'Peak' WHEN (H >= 8 AND H < 12) OR (H >= 18 AND H < 22) THEN 'Part-peak' ELSE 'Off-peak' END
                ELSE 'Off-peak' END AS Period
    FROM s)
SELECT m.Measure, m.Expected, m.Actual,
       CASE WHEN m.Actual IS NULL THEN 'NOT LOADED' WHEN ABS(m.Actual - m.Expected) < 0.5 THEN 'PASS' ELSE 'FAIL' END AS Status
FROM (
    SELECT 1 AS Ord, 'Peak kWh' AS Measure, 412800.0 AS Expected, (SELECT SUM(Value) FROM c WHERE Pt = 'Delivered kWh 15m' AND Period = 'Peak') AS Actual
    UNION ALL SELECT 2, 'Part-peak kWh', 368400, (SELECT SUM(Value) FROM c WHERE Pt = 'Delivered kWh 15m' AND Period = 'Part-peak')
    UNION ALL SELECT 3, 'Off-peak kWh', 731200, (SELECT SUM(Value) FROM c WHERE Pt = 'Delivered kWh 15m' AND Period = 'Off-peak')
    UNION ALL SELECT 4, 'Total kWh', 1512400, (SELECT SUM(Value) FROM c WHERE Pt = 'Delivered kWh 15m')
    UNION ALL SELECT 5, 'Peak intervals', 528, (SELECT NULLIF(COUNT(*), 0) FROM c WHERE Pt = 'Delivered kWh 15m' AND Period = 'Peak')
    UNION ALL SELECT 6, 'Part-peak intervals', 704, (SELECT NULLIF(COUNT(*), 0) FROM c WHERE Pt = 'Delivered kWh 15m' AND Period = 'Part-peak')
    UNION ALL SELECT 7, 'Off-peak intervals', 1744, (SELECT NULLIF(COUNT(*), 0) FROM c WHERE Pt = 'Delivered kWh 15m' AND Period = 'Off-peak')
    UNION ALL SELECT 8, 'Readings, Delivered kWh 15m', 2976, (SELECT NULLIF(COUNT(*), 0) FROM c WHERE Pt = 'Delivered kWh 15m')
    UNION ALL SELECT 9, 'Readings, Demand kW 15m', 2976, (SELECT NULLIF(COUNT(*), 0) FROM c WHERE Pt = 'Demand kW 15m')
    UNION ALL SELECT 10, 'Maximum 15-minute kW', 3240, (SELECT MAX(Value) FROM c WHERE Pt = 'Demand kW 15m')
) m
ORDER BY m.Ord;
GO

PRINT '== mdef_valley_electric_month: January 2024 on the three Valley Electric MDEF recorders (local stamps after 2024-01-01 00:00 up to and including 2024-02-01 00:00): 2976 readings on each of the six points (31 days x 96) and no day that is not 96. Assumed month, the one the recipe names for the first file; change the dates to the month delivered ==';
SELECT n.Description AS Node, p.Description AS Point, 2976 AS ExpectedReadings, COUNT(a.PtID) AS Readings,
       (SELECT COUNT(*) FROM (SELECT 1 AS One FROM dbo.AnalogArchive_TBL x
                              WHERE x.PtID = p.PtID AND x.LocalTimeStamp > '20240101' AND x.LocalTimeStamp <= '20240201'
                              GROUP BY CONVERT(date, DATEADD(MINUTE, -1, x.LocalTimeStamp)) HAVING COUNT(*) <> 96) q) AS DaysNot96,
       CASE WHEN COUNT(a.PtID) = 0 THEN 'NOT LOADED'
            WHEN COUNT(a.PtID) = 2976 AND (SELECT COUNT(*) FROM (SELECT 1 AS One FROM dbo.AnalogArchive_TBL x
                                                                 WHERE x.PtID = p.PtID AND x.LocalTimeStamp > '20240101' AND x.LocalTimeStamp <= '20240201'
                                                                 GROUP BY CONVERT(date, DATEADD(MINUTE, -1, x.LocalTimeStamp)) HAVING COUNT(*) <> 96) q) = 0 THEN 'PASS'
            ELSE 'FAIL' END AS Status
FROM dbo.PointDef_TBL p
JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
LEFT JOIN dbo.AnalogArchive_TBL a ON a.PtID = p.PtID AND a.LocalTimeStamp > '20240101' AND a.LocalTimeStamp <= '20240201'
WHERE o.Descriptor = 'Northlake VED MDEF Interval Import' AND n.Description IN ('MV90-MDEF-VED-SCIENCE', 'MV90-MDEF-VED-RECREATION', 'MV90-MDEF-VED-PLANT')
GROUP BY n.Description, p.PtID, p.Description
ORDER BY n.Description, p.Description;
GO

PRINT '== mv9_helios_rules: the five Helios MV9 points. Each rule is a count of violating readings and must be 0: a negative value on any point; a generation or irradiance value above 0 in the local hours 22:00 to 04:00; an export above the generation of the same interval at the Science Center array (the 2025-03 gap rows have no value and fall out of the join). Readings is how many readings were found; 0 means NOT LOADED ==';
WITH h AS (
    SELECT p.Description AS Pt, p.GwPtParam3 AS Recorder, a.UTCTimeStamp, a.Value,
           DATEPART(HOUR, DATEADD(MINUTE, -1, a.LocalTimeStamp)) AS Hr
    FROM dbo.AnalogArchive_TBL a
    JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
    JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
    JOIN dbo.ObjectRegistry o ON o.hSiERtdb = n.PtGatewayID
    WHERE o.Descriptor = 'Northlake Helios MV90 Generation Import' AND n.Description = 'MV90-MV9-HELIOS')
SELECT r.RuleText, 0 AS Expected, r.Actual, (SELECT COUNT(*) FROM h) AS Readings,
       CASE WHEN (SELECT COUNT(*) FROM h) = 0 THEN 'NOT LOADED' WHEN r.Actual = 0 THEN 'PASS' ELSE 'FAIL' END AS Status
FROM (
    SELECT 1 AS Ord, 'readings below zero' AS RuleText, (SELECT COUNT(*) FROM h WHERE Value < 0) AS Actual
    UNION ALL SELECT 2, 'generation or irradiance above zero between 22:00 and 04:00 local',
        (SELECT COUNT(*) FROM h WHERE (Pt LIKE 'Generated%' OR Pt LIKE 'Plane-of-Array%') AND (Hr >= 22 OR Hr < 4) AND Value > 0)
    UNION ALL SELECT 3, 'Science Center export above generation in the same interval',
        (SELECT COUNT(*) FROM h g JOIN h x ON x.Recorder = g.Recorder AND x.UTCTimeStamp = g.UTCTimeStamp AND x.Pt LIKE 'Exported%'
         WHERE g.Recorder = 'HOSSCIENCE01' AND g.Pt LIKE 'Generated%' AND x.Value > g.Value + 0.000001)
) r
ORDER BY r.Ord;
GO

PRINT '== bacnet_history_tie_out: Science Center chilled water (node NTP-BACNET-SCIENCE-CHW) must reproduce the Thermal Plant statements once a history path loads it: Delivered Ton-Hours 60m sums to 180860 over July 2024 (local stamps after 2024-07-01 00:00 up to and including 2024-08-01 00:00) and 58640 over March 2025, and Demand Tons 60m peaks at 542 in July 2024 and 214 in March 2025. Nothing in the recipe loads that history today, so NOT LOADED is the expected result until one does ==';
SELECT m.Measure, m.Expected, m.Actual,
       CASE WHEN m.Actual IS NULL THEN 'NOT LOADED' WHEN ABS(m.Actual - m.Expected) < 0.5 THEN 'PASS' ELSE 'FAIL' END AS Status
FROM (
    SELECT 1 AS Ord, 'Ton-Hours sum, July 2024' AS Measure, 180860.0 AS Expected,
           (SELECT SUM(a.Value) FROM dbo.AnalogArchive_TBL a JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
            WHERE n.Description = 'NTP-BACNET-SCIENCE-CHW' AND p.Description = 'Delivered Ton-Hours 60m' AND a.LocalTimeStamp > '20240701' AND a.LocalTimeStamp <= '20240801') AS Actual
    UNION ALL SELECT 2, 'Ton-Hours sum, March 2025', 58640,
           (SELECT SUM(a.Value) FROM dbo.AnalogArchive_TBL a JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
            WHERE n.Description = 'NTP-BACNET-SCIENCE-CHW' AND p.Description = 'Delivered Ton-Hours 60m' AND a.LocalTimeStamp > '20250301' AND a.LocalTimeStamp <= '20250401')
    UNION ALL SELECT 3, 'Tons maximum, July 2024', 542,
           (SELECT MAX(a.Value) FROM dbo.AnalogArchive_TBL a JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
            WHERE n.Description = 'NTP-BACNET-SCIENCE-CHW' AND p.Description = 'Demand Tons 60m' AND a.LocalTimeStamp > '20240701' AND a.LocalTimeStamp <= '20240801')
    UNION ALL SELECT 4, 'Tons maximum, March 2025', 214,
           (SELECT MAX(a.Value) FROM dbo.AnalogArchive_TBL a JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
            WHERE n.Description = 'NTP-BACNET-SCIENCE-CHW' AND p.Description = 'Demand Tons 60m' AND a.LocalTimeStamp > '20250301' AND a.LocalTimeStamp <= '20250401')
) m
ORDER BY m.Ord;
GO

PRINT '== noaa_observation_sanity: the observation points of NOAA-KSAC, NOAA-KSMF and NOAA-KSUU cannot have a fixed value (live public data), so this asserts what must hold for any real reading: a violation count that must be 0 for relative humidity outside 0 to 100, wind below zero, dew point above the temperature of the same stamp (the two points are in the same unit at each station), and a reading stamped more than an hour in the future. Readings 0 means NOT LOADED ==';
WITH st AS (SELECT * FROM (VALUES ('NOAA-KSAC', 'KSAC'), ('NOAA-KSMF', 'KSMF'), ('NOAA-KSUU', 'KSUU')) v (Node, Prefix)),
o AS (
    SELECT n.Description AS Node, p.Description AS Pt, a.UTCTimeStamp, a.Value
    FROM dbo.AnalogArchive_TBL a
    JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
    JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
    JOIN dbo.ObjectRegistry g ON g.hSiERtdb = n.PtGatewayID
    WHERE g.Descriptor = 'Northlake NOAA Weather' AND n.Description IN ('NOAA-KSAC', 'NOAA-KSMF', 'NOAA-KSUU'))
SELECT st.Node AS Station, r.RuleText, 0 AS Expected,
       CASE r.Ord WHEN 1 THEN (SELECT COUNT(*) FROM o WHERE o.Node = st.Node AND o.Pt = st.Prefix + ' Relative Humidity' AND (o.Value < 0 OR o.Value > 100))
                  WHEN 2 THEN (SELECT COUNT(*) FROM o WHERE o.Node = st.Node AND o.Pt = st.Prefix + ' Wind Speed' AND o.Value < 0)
                  WHEN 3 THEN (SELECT COUNT(*) FROM o d JOIN o t ON t.Node = d.Node AND t.UTCTimeStamp = d.UTCTimeStamp AND t.Pt = st.Prefix + ' Outside Air Temperature'
                               WHERE d.Node = st.Node AND d.Pt = st.Prefix + ' Dew Point' AND d.Value > t.Value + 0.01)
                  ELSE (SELECT COUNT(*) FROM o WHERE o.Node = st.Node AND o.UTCTimeStamp > DATEADD(HOUR, 1, GETUTCDATE())) END AS Actual,
       (SELECT COUNT(*) FROM o WHERE o.Node = st.Node) AS Readings,
       CASE WHEN (SELECT COUNT(*) FROM o WHERE o.Node = st.Node) = 0 THEN 'NOT LOADED'
            WHEN CASE r.Ord WHEN 1 THEN (SELECT COUNT(*) FROM o WHERE o.Node = st.Node AND o.Pt = st.Prefix + ' Relative Humidity' AND (o.Value < 0 OR o.Value > 100))
                            WHEN 2 THEN (SELECT COUNT(*) FROM o WHERE o.Node = st.Node AND o.Pt = st.Prefix + ' Wind Speed' AND o.Value < 0)
                            WHEN 3 THEN (SELECT COUNT(*) FROM o d JOIN o t ON t.Node = d.Node AND t.UTCTimeStamp = d.UTCTimeStamp AND t.Pt = st.Prefix + ' Outside Air Temperature'
                                         WHERE d.Node = st.Node AND d.Pt = st.Prefix + ' Dew Point' AND d.Value > t.Value + 0.01)
                            ELSE (SELECT COUNT(*) FROM o WHERE o.Node = st.Node AND o.UTCTimeStamp > DATEADD(HOUR, 1, GETUTCDATE())) END = 0 THEN 'PASS'
            ELSE 'FAIL' END AS Status
FROM st
CROSS JOIN (VALUES (1, 'humidity outside 0 to 100'), (2, 'wind below zero'), (3, 'dew point above temperature'), (4, 'reading stamped in the future')) r (Ord, RuleText)
ORDER BY st.Node, r.Ord;
GO

PRINT '== noaa_history_scope: after the History run (HistoryStartUtc 2024-01-01T08:00:00Z) the twelve observation points hold readings from 2024-01-01 and the eighteen forecast points hold none stamped before 2026-11-01 (assumed: the day the history run is made; History never writes the forecast points). Expected 12 and 0. NOT LOADED until the history run has stored observations ==';
WITH pts AS (
    SELECT p.PtID, n.Description AS Node,
           CASE WHEN n.Description LIKE '%FORECAST' THEN 'Forecast' ELSE 'Observation' END AS Kind
    FROM dbo.PointDef_TBL p
    JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
    JOIN dbo.ObjectRegistry g ON g.hSiERtdb = n.PtGatewayID
    WHERE g.Descriptor = 'Northlake NOAA Weather'),
firsts AS (
    SELECT pts.PtID, pts.Kind, MIN(a.UTCTimeStamp) AS FirstUTC
    FROM pts JOIN dbo.AnalogArchive_TBL a ON a.PtID = pts.PtID
    GROUP BY pts.PtID, pts.Kind)
SELECT m.Measure, m.Expected, m.Actual,
       CASE WHEN (SELECT COUNT(*) FROM firsts WHERE Kind = 'Observation' AND FirstUTC < '20240102') = 0 THEN 'NOT LOADED'
            WHEN m.Actual = m.Expected THEN 'PASS' ELSE 'FAIL' END AS Status
FROM (
    SELECT 1 AS Ord, 'observation points with a reading before 2024-01-02' AS Measure, 12 AS Expected,
           (SELECT COUNT(*) FROM firsts WHERE Kind = 'Observation' AND FirstUTC < '20240102') AS Actual
    UNION ALL SELECT 2, 'forecast points with a reading before 2026-11-01', 0,
           (SELECT COUNT(*) FROM firsts WHERE Kind = 'Forecast' AND FirstUTC < '20261101')
) m
ORDER BY m.Ord;
GO

PRINT '== spinwave_days: the two SPINWAVE-SCIENCE-LAB points hold 144 readings (10 minutes) on every local day loaded, leaving out the first and last day loaded (a delivery can end mid-day) and the four daylight-saving days 2024-03-10, 2024-11-03, 2025-03-09 and 2025-11-02. Expected 0 days not at 144; NOT LOADED when the point has no readings ==';
WITH d AS (
    SELECT p.PtID, p.Description AS Pt, CONVERT(date, DATEADD(MINUTE, -1, a.LocalTimeStamp)) AS Day, COUNT(*) AS Readings
    FROM dbo.PointDef_TBL p
    JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
    JOIN dbo.AnalogArchive_TBL a ON a.PtID = p.PtID
    WHERE n.Description = 'SPINWAVE-SCIENCE-LAB'
    GROUP BY p.PtID, p.Description, CONVERT(date, DATEADD(MINUTE, -1, a.LocalTimeStamp)))
SELECT d.Pt AS Point, COUNT(*) AS DaysLoaded, 0 AS ExpectedDaysNot144,
       SUM(CASE WHEN d.Readings <> 144 AND d.Day > b.FirstDay AND d.Day < b.LastDay
                 AND d.Day NOT IN ('20240310', '20241103', '20250309', '20251102') THEN 1 ELSE 0 END) AS DaysNot144,
       CASE WHEN SUM(CASE WHEN d.Readings <> 144 AND d.Day > b.FirstDay AND d.Day < b.LastDay
                           AND d.Day NOT IN ('20240310', '20241103', '20250309', '20251102') THEN 1 ELSE 0 END) = 0 THEN 'PASS' ELSE 'FAIL' END AS Status
FROM d
JOIN (SELECT PtID, MIN(Day) AS FirstDay, MAX(Day) AS LastDay FROM d GROUP BY PtID) b ON b.PtID = d.PtID
GROUP BY d.PtID, d.Pt
UNION ALL
SELECT p.Description, 0, 0, 0, 'NOT LOADED'
FROM dbo.PointDef_TBL p JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
WHERE n.Description = 'SPINWAVE-SCIENCE-LAB' AND NOT EXISTS (SELECT 1 FROM dbo.AnalogArchive_TBL a WHERE a.PtID = p.PtID)
ORDER BY 1;
GO

PRINT '== fig_cedar_row_water_days: the Cedar Row A Water Master point (FIG-CEDAR-ROW) after the seven FIG encodings of the same day, each run on its own day: 7 days loaded, no day that is not 24 hourly readings (the four daylight-saving days left out), and no hour whose value differs from the same hour of the first day loaded. NOT LOADED until the first case has run ==';
WITH h AS (
    SELECT CONVERT(date, DATEADD(MINUTE, -1, a.LocalTimeStamp)) AS Day, DATEPART(HOUR, DATEADD(MINUTE, -1, a.LocalTimeStamp)) AS Hr, a.Value
    FROM dbo.AnalogArchive_TBL a
    JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID
    JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
    WHERE n.Description = 'FIG-CEDAR-ROW'),
dd AS (SELECT Day, COUNT(*) AS Readings FROM h GROUP BY Day)
SELECT m.Measure, m.Expected, m.Actual,
       CASE WHEN (SELECT COUNT(*) FROM dd) = 0 THEN 'NOT LOADED' WHEN m.Actual = m.Expected THEN 'PASS' ELSE 'FAIL' END AS Status
FROM (
    SELECT 1 AS Ord, 'days loaded' AS Measure, 7 AS Expected, (SELECT COUNT(*) FROM dd) AS Actual
    UNION ALL SELECT 2, 'days not at 24 readings', 0, (SELECT COUNT(*) FROM dd WHERE Readings <> 24 AND Day NOT IN ('20240310', '20241103', '20250309', '20251102'))
    UNION ALL SELECT 3, 'hours that differ from the first day loaded', 0,
           (SELECT COUNT(*) FROM h x JOIN h f ON f.Day = (SELECT MIN(Day) FROM dd) AND f.Hr = x.Hr WHERE x.Day <> f.Day AND ABS(x.Value - f.Value) > 0.000001)
) m
ORDER BY m.Ord;
GO

PRINT '== fixed_network_days: the fixed-network submeter nodes after both deliveries. Points with readings: FIG-CEDAR-ROW-A-UNITS 61, FIG-CEDAR-ROW-B-UNITS 65, FIG-CAMPUS-SUBMETERS 1 (the Lakeview Hall laundry point is Disabled, so 127 load, not 128). Per node, points with a local day that is not 24 hourly readings (leaving out the node''s first and last day and the four daylight-saving days) must be 0, and the laundry point must hold no reading at all ==';
WITH pd AS (
    SELECT n.Description AS Node, p.PtID, CONVERT(date, DATEADD(MINUTE, -1, a.LocalTimeStamp)) AS Day, COUNT(*) AS Readings
    FROM dbo.PointDef_TBL p
    JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
    JOIN dbo.ObjectRegistry g ON g.hSiERtdb = n.PtGatewayID
    JOIN dbo.AnalogArchive_TBL a ON a.PtID = p.PtID
    WHERE g.Descriptor = 'Northlake Fixed Network Submeters'
    GROUP BY n.Description, p.PtID, CONVERT(date, DATEADD(MINUTE, -1, a.LocalTimeStamp))),
b AS (SELECT Node, MIN(Day) AS FirstDay, MAX(Day) AS LastDay FROM pd GROUP BY Node)
SELECT m.Node, m.Measure, m.Expected, m.Actual,
       CASE WHEN NOT EXISTS (SELECT 1 FROM pd WHERE pd.Node = m.Node) THEN 'NOT LOADED' WHEN m.Actual = m.Expected THEN 'PASS' ELSE 'FAIL' END AS Status
FROM (
    SELECT e.Node, 'points with readings' AS Measure, e.Expected,
           (SELECT COUNT(DISTINCT pd.PtID) FROM pd WHERE pd.Node = e.Node) AS Actual
    FROM (VALUES ('FIG-CEDAR-ROW-A-UNITS', 61), ('FIG-CEDAR-ROW-B-UNITS', 65), ('FIG-CAMPUS-SUBMETERS', 1)) e (Node, Expected)
    UNION ALL
    SELECT e.Node, 'points with a day not at 24 readings', 0,
           (SELECT COUNT(DISTINCT pd.PtID) FROM pd JOIN b ON b.Node = pd.Node
            WHERE pd.Node = e.Node AND pd.Readings <> 24 AND pd.Day > b.FirstDay AND pd.Day < b.LastDay AND pd.Day NOT IN ('20240310', '20241103', '20250309', '20251102'))
    FROM (VALUES ('FIG-CEDAR-ROW-A-UNITS'), ('FIG-CEDAR-ROW-B-UNITS'), ('FIG-CAMPUS-SUBMETERS')) e (Node)
    UNION ALL
    SELECT 'FIG-CAMPUS-SUBMETERS', 'readings on the disabled Lakeview Hall laundry point', 0,
           (SELECT COUNT(*) FROM dbo.PointDef_TBL p JOIN dbo.AnalogArchive_TBL a ON a.PtID = p.PtID WHERE p.GwPtParam2 = 'FN_LAKEVIEW_LAUNDRY_E')
) m
ORDER BY m.Node, m.Measure;
GO

PRINT '== feed_archive_intervals: every archived row of the Modbus (1 minute), ODBC (30 minute) and BACnet (60 minute, the steam header pressure 15) points carries the interval its Description ends with (for example 60m). Wrong is the count of rows with another interval and must be 0; NOT LOADED when the point has no rows ==';
SELECT n.Description AS Node, p.Description AS Point, x.ExpectedInterval, COUNT(a.PtID) AS Rows,
       SUM(CASE WHEN a.PtID IS NOT NULL AND a.Interval <> x.ExpectedInterval THEN 1 ELSE 0 END) AS Wrong,
       CASE WHEN COUNT(a.PtID) = 0 THEN 'NOT LOADED'
            WHEN SUM(CASE WHEN a.Interval <> x.ExpectedInterval THEN 1 ELSE 0 END) = 0 THEN 'PASS' ELSE 'FAIL' END AS Status
FROM dbo.PointDef_TBL p
JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
JOIN dbo.ObjectRegistry g ON g.hSiERtdb = n.PtGatewayID
CROSS APPLY (SELECT TRY_CONVERT(int, LEFT(RIGHT(p.Description, CHARINDEX(' ', REVERSE(p.Description)) - 1), CHARINDEX(' ', REVERSE(p.Description)) - 2)) AS ExpectedInterval) x
LEFT JOIN dbo.AnalogArchive_TBL a ON a.PtID = p.PtID
WHERE g.Descriptor IN ('Northlake Thermal Plant Modbus', 'Northlake ODBC Historian', 'Northlake Thermal Plant BACnet')
GROUP BY n.Description, p.PtID, p.Description, x.ExpectedInterval
ORDER BY n.Description, p.Description;
GO

PRINT '== fake_smoke_day: the Fake Gateway smoke point (FAKE-SMOKE) holds 96 sinusoidal readings for 2024-01-01 (UTC stamps 2024-01-01 08:00 through 2024-01-02 07:45, the schedule''s StartTimestamp and EndTimestamp), every one between 12 and 36 (MinValue 12, MaxValue 36) ==';
SELECT m.Measure, m.Expected, m.Actual,
       CASE WHEN (SELECT COUNT(*) FROM dbo.AnalogArchive_TBL a JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID WHERE n.Description = 'FAKE-SMOKE') = 0 THEN 'NOT LOADED'
            WHEN m.Measure = 'readings' AND m.Actual = m.Expected THEN 'PASS'
            WHEN m.Measure = 'lowest value (at least)' AND m.Actual >= m.Expected THEN 'PASS'
            WHEN m.Measure = 'highest value (at most)' AND m.Actual <= m.Expected THEN 'PASS'
            ELSE 'FAIL' END AS Status
FROM (
    SELECT 1 AS Ord, 'readings' AS Measure, 96.0 AS Expected,
           (SELECT COUNT(*) FROM dbo.AnalogArchive_TBL a JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
            WHERE n.Description = 'FAKE-SMOKE' AND a.UTCTimeStamp >= '20240101 08:00' AND a.UTCTimeStamp <= '20240102 07:45') AS Actual
    UNION ALL SELECT 2, 'lowest value (at least)', 12,
           (SELECT MIN(a.Value) FROM dbo.AnalogArchive_TBL a JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
            WHERE n.Description = 'FAKE-SMOKE' AND a.UTCTimeStamp >= '20240101 08:00' AND a.UTCTimeStamp <= '20240102 07:45')
    UNION ALL SELECT 3, 'highest value (at most)', 36,
           (SELECT MAX(a.Value) FROM dbo.AnalogArchive_TBL a JOIN dbo.PointDef_TBL p ON p.PtID = a.PtID JOIN dbo.GwNodes n ON n.GwNodeID = p.GwNodeID
            WHERE n.Description = 'FAKE-SMOKE' AND a.UTCTimeStamp >= '20240101 08:00' AND a.UTCTimeStamp <= '20240102 07:45')
) m
ORDER BY m.Ord;
GO
